                                    tiltMaxAngleY={5}
                                    perspective={1000}
                                    scale={1.02}
                                    transitionSpeed={1500}
                                    className="break-inside-avoid"
                                >
                                    <div
                                        className={cn(
                                            "relative group overflow-hidden cursor-pointer rounded-2xl bg-white/5 border border-white/5 hover:border-teal/30 transition-all duration-700",
                                            item.height
                                        )}
                                    >
