"use client";

import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import NetworkSidebar from "@/components/network/Sidebar";
import { createClient } from "@/lib/supabase/client";
import {
    Users,
    ListTodo,
    Calendar,
    TrendingUp,
    CheckCircle,
    AlertCircle,
    RefreshCw
} from "lucide-react";

export default function DashboardPage() {
    const { profile, isPresident, isCoreCouncil } = useAuth();
    const [stats, setStats] = useState({
        totalMembers: 0,
        totalTeams: 0,
        pendingTasks: 0,
        upcomingEvents: 0
    });
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(false);
    const supabase = createClient();

    const fetchStats = async () => {
        if (!profile?.id) return;
        setLoading(true);
        setError(false);

        try {
            // Fetch team count
            const teamPromise = supabase
                .from("teams")
                .select("*", { count: "exact", head: true });

            // Fetch member count
            const memberPromise = supabase
                .from("profiles")
                .select("*", { count: "exact", head: true });

            // Promise.race to handle timeout elegantly without throwing unhandled rejection
            const timeoutPromise = new Promise((resolve) => {
                setTimeout(() => resolve({ timeout: true }), 15000); // 15s timeout
            });

            const result = await Promise.race([
                Promise.all([teamPromise, memberPromise]),
                timeoutPromise
            ]);

            if (result.timeout) {
                console.warn("Stats fetch timed out");
                setError(true);
            } else {
                const [teamResult, memberResult] = result;

                if (teamResult.error || memberResult.error) {
                    console.warn("Stats fetch error:", teamResult.error || memberResult.error);
                    setError(true);
                } else {
                    setStats({
                        totalMembers: memberResult.count || 0,
                        totalTeams: teamResult.count || 0,
                        pendingTasks: 0,
                        upcomingEvents: 0
                    });
                }
            }
        } catch (err) {
            console.error("Error fetching stats:", err);
            setError(true);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchStats();
    }, [profile, fetchStats]);

    const getGreeting = () => {
        const hour = new Date().getHours();
        if (hour < 12) return "Good Morning";
        if (hour < 17) return "Good Afternoon";
        return "Good Evening";
    };

    const statCards = [
        {
            title: "Total Members",
            value: stats.totalMembers,
            icon: Users,
            color: "teal",
            visible: isPresident() || isCoreCouncil()
        },
        {
            title: "Active Teams",
            value: stats.totalTeams,
            icon: TrendingUp,
            color: "lime",
            visible: true
        },
        {
            title: "Pending Tasks",
            value: stats.pendingTasks,
            icon: ListTodo,
            color: "orange",
            visible: true
        },
        {
            title: "Upcoming Events",
            value: stats.upcomingEvents,
            icon: Calendar,
            color: "purple",
            visible: true
        }
    ];

    return (
        <div className="flex min-h-screen">
            <NetworkSidebar />

            <main className="flex-1 p-4 lg:p-10 pt-24 lg:pt-10 overflow-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mb-6 md:mb-10"
                >
                    <h1 className="text-2xl md:text-3xl lg:text-4xl font-serif font-bold text-white mb-2">
                        {getGreeting()}, <span className="text-teal">{profile?.full_name?.split(' ')[0] || 'Member'}</span>
                    </h1>
                    <p className="text-white/50 text-sm md:text-base">
                        Welcome to the RMC Network. Here&apos;s your overview.
                    </p>
                </motion.div>

                {/* Error State with Retry */}
                {error && (
                    <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="mb-6 p-4 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center justify-between"
                    >
                        <div className="flex items-center gap-3 text-red-400">
                            <AlertCircle className="w-5 h-5" />
                            <span className="text-sm">Failed to load data. Check your connection.</span>
                        </div>
                        <button
                            onClick={fetchStats}
                            className="flex items-center gap-2 px-3 py-1.5 bg-red-500/20 hover:bg-red-500/30 text-red-400 rounded-lg text-sm transition-colors"
                        >
                            <RefreshCw className="w-4 h-4" />
                            Retry
                        </button>
                    </motion.div>
                )}

                {/* Stats Grid */}
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4 mb-6 md:mb-10">
                    {statCards.filter(card => card.visible).map((card, index) => {
                        const Icon = card.icon;
                        const colorClass = {
                            teal: 'from-teal/20 to-teal/5 border-teal/20',
                            lime: 'from-lime/20 to-lime/5 border-lime/20',
                            orange: 'from-orange/20 to-orange/5 border-orange/20',
                            purple: 'from-purple-500/20 to-purple-500/5 border-purple-500/20'
                        }[card.color];

                        const iconColor = {
                            teal: 'text-teal',
                            lime: 'text-lime',
                            orange: 'text-orange',
                            purple: 'text-purple-400'
                        }[card.color];

                        return (
                            <motion.div
                                key={card.title}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: index * 0.1 }}
                                className={`bg-gradient-to-br ${colorClass} backdrop-blur-xl border rounded-xl md:rounded-2xl p-4 md:p-6`}
                            >
                                <div className="flex items-center justify-between mb-2 md:mb-4">
                                    <Icon className={`w-6 h-6 md:w-8 md:h-8 ${iconColor}`} />
                                    {loading ? (
                                        <div className="w-6 h-6 md:w-8 md:h-8 bg-white/10 rounded animate-pulse" />
                                    ) : (
                                        <span className="text-2xl md:text-3xl font-bold text-white">{card.value}</span>
                                    )}
                                </div>
                                <h3 className="text-white/60 text-xs md:text-sm font-medium">{card.title}</h3>
                            </motion.div>
                        );
                    })}
                </div>

                {/* Quick Actions */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-xl md:rounded-2xl p-4 md:p-6"
                >
                    <h2 className="text-lg md:text-xl font-serif font-bold text-white mb-3 md:mb-4">Quick Actions</h2>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
                        <QuickAction
                            href="/network/tasks"
                            icon={ListTodo}
                            label="View Tasks"
                            color="teal"
                        />
                        <QuickAction
                            href="/network/calendar"
                            icon={Calendar}
                            label="Calendar"
                            color="lime"
                        />
                        <QuickAction
                            href="/network/resources"
                            icon={CheckCircle}
                            label="Resources"
                            color="orange"
                        />
                        {isPresident() && (
                            <QuickAction
                                href="/network/settings"
                                icon={AlertCircle}
                                label="Settings"
                                color="purple"
                            />
                        )}
                    </div>
                </motion.div>

                {/* Upcoming Widget */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.4 }}
                    className="mt-4 md:mt-8 bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-xl md:rounded-2xl p-4 md:p-6"
                >
                    <h2 className="text-lg md:text-xl font-serif font-bold text-white mb-3 md:mb-4">Upcoming</h2>
                    <div className="flex items-center justify-center h-32 md:h-48 border border-dashed border-white/10 rounded-xl">
                        <p className="text-white/30 text-xs md:text-sm">Calendar widget coming soon...</p>
                    </div>
                </motion.div>
            </main>
        </div>
    );
}

function QuickAction({ href, icon: Icon, label, color }) {
    const colorClass = {
        teal: 'hover:border-teal/50 hover:bg-teal/5 active:bg-teal/10',
        lime: 'hover:border-lime/50 hover:bg-lime/5 active:bg-lime/10',
        orange: 'hover:border-orange/50 hover:bg-orange/5 active:bg-orange/10',
        purple: 'hover:border-purple-500/50 hover:bg-purple-500/5 active:bg-purple-500/10'
    }[color];

    const iconColor = {
        teal: 'group-hover:text-teal',
        lime: 'group-hover:text-lime',
        orange: 'group-hover:text-orange',
        purple: 'group-hover:text-purple-400'
    }[color];

    return (
        <a
            href={href}
            className={`group flex flex-col items-center gap-2 p-3 md:p-4 bg-white/5 border border-white/10 rounded-xl transition-all ${colorClass}`}
        >
            <Icon className={`w-5 h-5 md:w-6 md:h-6 text-white/50 ${iconColor} transition-colors`} />
            <span className="text-white/70 text-xs md:text-sm text-center group-hover:text-white transition-colors">{label}</span>
        </a>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter, usePathname } from "next/navigation";
import { AuthProvider, useAuth } from "@/context/AuthContext";

function NetworkLayoutInner({ children }) {
    const { loading: _loading, authReady, user, signOut } = useAuth();
    const router = useRouter();
    const pathname = usePathname();
    const [timedOut, setTimedOut] = useState(false);

    // Timeout fallback - if auth doesn't resolve in 8 seconds, redirect to login
    useEffect(() => {
        const timer = setTimeout(() => {
            if (!authReady) {
                console.warn("Auth loading timed out, redirecting to login");
                setTimedOut(true);
            }
        }, 20000); // 20 second timeout

        return () => clearTimeout(timer);
    }, [authReady]);

    // Handle authentication redirects
    useEffect(() => {
        const handleRedirects = async () => {
            // Case 1: Timeout occurred - Force sign out and redirect to login
            if (timedOut) {
                if (pathname !== "/network/login") {
                    console.warn("Auth timeout - forcing sign out and redirect");
                    try {
                        await signOut();
                    } catch (_e) {
                        console.error("Error clearing session on timeout:", _e);
                    }
                    router.replace("/network/login");
                }
                return;
            }

            // Case 2: Auth is still loading -> Wait
            if (!authReady) return;

            const isLoginPage = pathname === "/network/login";

            // Case 3: Not logged in -> Redirect to login
            if (!user && !isLoginPage) {
                // User is already logged out (null), so just redirect.
                router.replace("/network/login");
            }

            // Case 4: Logged in and on login page -> Redirect to dashboard
            if (user && isLoginPage) {
                router.replace("/network/dashboard");
            }
        };

        handleRedirects();
    }, [authReady, timedOut, user, pathname, router, signOut]);

    // Show loading while auth is initializing (but not forever)
    if (!authReady && !timedOut) {
        return (
            <div className="min-h-screen bg-[#020617] flex items-center justify-center">
                <div className="flex flex-col items-center gap-4">
                    <div className="w-12 h-12 border-2 border-teal/30 border-t-teal rounded-full animate-spin" />
                    <p className="text-white/50 text-sm font-mono">Loading Network...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#020617]">
            {children}
        </div>
    );
}

export default function NetworkLayout({ children }) {
    return (
        <AuthProvider>
            <NetworkLayoutInner>{children}</NetworkLayoutInner>
        </AuthProvider>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import NetworkSidebar from "@/components/network/Sidebar";
import { createClient } from "@/lib/supabase/client";
import {
    Users,
    Shield,
    Loader2,
    UserPlus,
    Trash2,
    Key,
    X
} from "lucide-react";
import ConfirmationModal from "@/components/ui/ConfirmationModal";
import { updateMemberPassword, createTeamMember } from "@/app/network/actions";

export default function MyTeamPage() {
    const { profile } = useAuth();
    const [invites, setInvites] = useState({}); // Map of teamId -> invites[]
    const [showAddModal, setShowAddModal] = useState(false);
    const [selectedTeam, setSelectedTeam] = useState(null);
    const [myTeams, setMyTeams] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isDeleting, setIsDeleting] = useState(false);
    const [confirmModal, setConfirmModal] = useState({
        isOpen: false,
        title: "",
        message: "",
        onConfirm: () => { },
        isDangerous: false
    });

    // Password Modal State
    const [passwordModal, setPasswordModal] = useState({
        isOpen: false,
        teamId: null,
        memberId: null,
        memberName: ""
    });

    const supabase = createClient();

    useEffect(() => {
        fetchMyTeams();
    }, [profile]);

    const fetchMyTeams = async () => {
        if (!profile?.id) return;

        try {
            // Get teams the user belongs to
            const { data: teamMemberships, error } = await supabase
                .from("team_members")
                .select(`
                    id,
                    role,
                    team_id,
                    teams:team_id (
                        id,
                        name,
                        type,
                        description,
                        team_members (
                            id,
                            role,
                            user_id,
                            profiles:user_id (
                                id,
                                full_name,
                                email,
                                role
                            )
                        )
                    )
                `)
                .eq("user_id", profile.id);

            if (error) throw error;

            // Process data
            const teams = teamMemberships?.map(tm => ({
                ...tm.teams,
                myRole: tm.role
            })) || [];

            setMyTeams(teams);

            // Fetch invites for teams where user is head
            const headTeams = teams.filter(t => t.myRole === 'head');
            if (headTeams.length > 0) {
                fetchInvites(headTeams.map(t => t.id));
            }
        } catch (error) {
            console.error("Error fetching my teams:", error);
        } finally {
            setLoading(false);
        }
    };

    const fetchInvites = async (teamIds) => {
        try {
            const { data, error } = await supabase
                .from("team_invites")
                .select("*")
                .in("team_id", teamIds)
                .eq("status", "pending");

            if (error) throw error;

            // Group by team_id
            const invitesMap = {};
            data?.forEach(invite => {
                if (!invitesMap[invite.team_id]) invitesMap[invite.team_id] = [];
                invitesMap[invite.team_id].push(invite);
            });
            setInvites(invitesMap);
        } catch (error) {
            console.error("Error fetching invites:", error);
        }
    };

    const getHead = (team) => {
        const headMember = team.team_members?.find(m => m.role === "head");
        return headMember?.profiles;
    };

    const getMembers = (team) => {
        return team.team_members?.filter(m => m.role === "member").map(m => m.profiles) || [];
    };

    if (loading) {
        return (
            <div className="flex min-h-screen">
                <NetworkSidebar />
                <main className="flex-1 p-10 flex items-center justify-center">
                    <Loader2 className="w-10 h-10 text-teal animate-spin" />
                </main>
            </div>
        );
    }

    if (myTeams.length === 0) {
        return (
            <div className="flex min-h-screen">
                <NetworkSidebar />
                <main className="flex-1 p-10 flex items-center justify-center">
                    <div className="text-center">
                        <Users className="w-16 h-16 text-white/10 mx-auto mb-4" />
                        <h1 className="text-2xl font-serif text-white mb-2">No Teams</h1>
                        <p className="text-white/50">You&apos;re not part of any team yet.</p>
                    </div>
                </main>
            </div>
        );
    }



    const executeRemoveMember = async (teamId, memberId) => {
        setIsDeleting(true);
        try {
            const { error } = await supabase
                .from("team_members")
                .delete()
                .match({ team_id: teamId, user_id: memberId });

            if (error) throw error;

            fetchMyTeams();
            setConfirmModal(prev => ({ ...prev, isOpen: false }));
        } catch (error) {
            console.error("Error removing member:", error);
            setConfirmModal({
                isOpen: true,
                type: "error",
                title: "Error",
                message: "Failed to remove member. You might not have permission.",
                onConfirm: null
            });
        } finally {
            setIsDeleting(false);
        }
    };

    const handleRemoveMember = (teamId, memberId, memberName) => {
        setConfirmModal({
            isOpen: true,
            type: "confirm",
            title: "Remove Member",
            message: `Are you sure you want to remove ${memberName} from the team? This action cannot be undone.`,
            confirmText: "Remove Member",
            isDangerous: true,
            onConfirm: () => executeRemoveMember(teamId, memberId)
        });
    };

    return (
        <div className="flex min-h-screen">
            <NetworkSidebar />

            <main className="flex-1 p-6 lg:p-10 pt-24 lg:pt-10 overflow-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mb-10"
                >
                    <h1 className="text-3xl lg:text-4xl font-serif font-bold text-white mb-2">
                        My Team{myTeams.length > 1 ? "s" : ""}
                    </h1>
                    <p className="text-white/50">
                        View your team memberships and colleagues
                    </p>
                </motion.div>

                {/* Teams */}
                <div className="space-y-8">
                    {myTeams.map((team, index) => {
                        const head = getHead(team);
                        const members = getMembers(team);
                        const isHead = team.myRole === "head";
                        const teamInvites = invites[team.id] || [];

                        return (
                            <motion.div
                                key={team.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: index * 0.1 }}
                                className="bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-2xl overflow-hidden"
                            >
                                {/* Team Header */}
                                <div className={`px-6 py-5 border-b border-white/5 ${team.type === "fest"
                                    ? "bg-gradient-to-r from-purple-500/10 to-pink-500/10"
                                    : "bg-gradient-to-r from-teal/5 to-lime/5"
                                    }`}>
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <div className="flex items-center gap-3">
                                                <h2 className="text-xl font-serif font-bold text-white">{team.name}</h2>
                                                {isHead && (
                                                    <span className="px-2 py-0.5 text-[10px] uppercase tracking-widest bg-yellow-500/20 text-yellow-400 border border-yellow-500/30 rounded-full">
                                                        You&apos;re the Head
                                                    </span>
                                                )}
                                            </div>
                                            <p className="text-white/40 text-sm mt-1">{team.description || "No description"}</p>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <span className={`px-3 py-1 text-xs uppercase tracking-widest rounded-full ${team.type === "fest"
                                                ? "bg-purple-500/20 text-purple-400 border border-purple-500/30"
                                                : "bg-teal/20 text-teal border border-teal/30"
                                                }`}>
                                                {team.type === "fest" ? "Fest Team" : "General Team"}
                                            </span>

                                            {isHead && (
                                                <button
                                                    onClick={() => {
                                                        setSelectedTeam(team);
                                                        setShowAddModal(true);
                                                    }}
                                                    className="flex items-center gap-2 px-3 py-1.5 bg-white/10 hover:bg-white/20 text-white rounded-lg text-sm transition-colors border border-white/10"
                                                >
                                                    <UserPlus className="w-4 h-4" />
                                                    Add Member
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                </div>

                                {/* Team Members */}
                                <div className="p-6">
                                    {/* Head */}
                                    {head && (
                                        <div className="mb-6">
                                            <h3 className="text-[10px] uppercase tracking-widest text-white/30 font-mono mb-3">Team Head</h3>
                                            <div className="flex items-center gap-3 p-3 bg-yellow-500/5 border border-yellow-500/10 rounded-xl">
                                                <div className="w-10 h-10 bg-gradient-to-br from-yellow-500/30 to-orange-500/30 rounded-full flex items-center justify-center">
                                                    <Shield className="w-5 h-5 text-yellow-400" />
                                                </div>
                                                <div>
                                                    <p className="text-white font-medium">{head.full_name || "Unnamed"}</p>
                                                    <p className="text-white/40 text-sm">{head.email}</p>
                                                </div>
                                            </div>
                                        </div>
                                    )}

                                    {/* Invites (Only for Head) */}
                                    {isHead && teamInvites.length > 0 && (
                                        <div className="mb-6">
                                            <h3 className="text-[10px] uppercase tracking-widest text-white/30 font-mono mb-3">
                                                Pending Invites ({teamInvites.length})
                                            </h3>
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                                {teamInvites.map(invite => (
                                                    <div
                                                        key={invite.id}
                                                        className="flex items-center gap-3 p-3 bg-white/5 border border-white/10 border-dashed rounded-xl"
                                                    >
                                                        <div className="w-10 h-10 bg-white/5 rounded-full flex items-center justify-center">
                                                            <Loader2 className="w-4 h-4 text-white/30 animate-spin" />
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-white font-medium truncate">{invite.full_name || "Invited User"}</p>
                                                            <p className="text-white/40 text-sm truncate">{invite.email}</p>
                                                        </div>
                                                        <div className="px-2 py-1 bg-yellow-500/20 text-yellow-500 text-[10px] rounded">
                                                            Pending
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Members */}
                                    <div>
                                        <h3 className="text-[10px] uppercase tracking-widest text-white/30 font-mono mb-3">
                                            Members ({members.length})
                                        </h3>
                                        {members.length === 0 ? (
                                            <p className="text-white/30 text-sm">No other members in this team</p>
                                        ) : (
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                                {members.map(member => (
                                                    <div
                                                        key={member.id}
                                                        className="flex items-center gap-3 p-3 bg-white/5 border border-white/10 rounded-xl group relative"
                                                    >
                                                        <div className="w-10 h-10 bg-gradient-to-br from-teal/20 to-purple-500/20 rounded-full flex items-center justify-center">
                                                            <span className="text-white font-bold text-sm">
                                                                {member.full_name?.[0] || member.email?.[0] || "?"}
                                                            </span>
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-white font-medium truncate">{member.full_name || "Unnamed"}</p>
                                                            <p className="text-white/40 text-sm truncate">{member.email}</p>
                                                        </div>

                                                        {isHead && (
                                                            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                                <button
                                                                    onClick={() => setPasswordModal({
                                                                        isOpen: true,
                                                                        teamId: team.id,
                                                                        memberId: member.id,
                                                                        memberName: member.full_name
                                                                    })}
                                                                    className="p-2 bg-white/10 text-white/50 hover:text-white rounded-lg hover:bg-white/20"
                                                                    title="Update Password"
                                                                >
                                                                    <Key className="w-4 h-4" />
                                                                </button>
                                                                <button
                                                                    onClick={() => handleRemoveMember(team.id, member.id, member.full_name)}
                                                                    disabled={isDeleting}
                                                                    className="p-2 bg-red-500/10 text-red-400 rounded-lg hover:bg-red-500/20"
                                                                    title="Remove Member"
                                                                >
                                                                    <Trash2 className="w-4 h-4" />
                                                                </button>
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        );
                    })}
                </div>
            </main>

            {/* Add Member Modal */}
            {showAddModal && selectedTeam && (
                <AddMemberModal
                    team={selectedTeam}
                    onClose={() => {
                        setShowAddModal(false);
                        setSelectedTeam(null);
                    }}
                    onSuccess={() => {
                        fetchMyTeams(); // Refresh list
                    }}
                />
            )}


            <ConfirmationModal
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal(prev => ({ ...prev, isOpen: false }))}
                onConfirm={confirmModal.onConfirm}
                title={confirmModal.title}
                message={confirmModal.message}
                confirmText={confirmModal.confirmText}
                isDangerous={confirmModal.isDangerous}
                isLoading={isDeleting}
            />

            {/* Password Update Modal */}
            {passwordModal.isOpen && (
                <UpdatePasswordModal
                    isOpen={passwordModal.isOpen}
                    onClose={() => setPasswordModal({ ...passwordModal, isOpen: false })}
                    teamId={passwordModal.teamId}
                    memberId={passwordModal.memberId}
                    memberName={passwordModal.memberName}
                />
            )}
        </div>
    );
}

function AddMemberModal({ team, onClose, onSuccess }) {
    const { profile } = useAuth();
    const [email, setEmail] = useState("");
    const [name, setName] = useState("");
    const [password, setPassword] = useState("");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [successMsg, setSuccessMsg] = useState("");

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");
        setSuccessMsg("");
        setLoading(true);

        try {
            const cleanEmail = email.trim().toLowerCase();
            const cleanName = name.trim() || cleanEmail.split('@')[0];
            const cleanPassword = password.trim();

            if (cleanPassword.length < 6) {
                throw new Error("Password must be at least 6 characters.");
            }

            // Call Server Action
            const result = await createTeamMember(team.id, cleanEmail, cleanPassword, cleanName);

            if (!result.success) {
                throw new Error(result.error || "Failed to add member");
            }

            setSuccessMsg("Member added successfully! They can log in immediately.");

            setTimeout(() => {
                onSuccess();
                onClose();
            }, 1500);

        } catch (err) {
            console.error("Error adding member:", err);
            setError(err.message || "Failed to add member");
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="bg-gray-900 border border-white/10 rounded-2xl w-full max-w-md p-6"
            >
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-serif font-bold text-white">Add Member to {team.name}</h3>
                    <button onClick={onClose}><X className="text-white/50 hover:text-white" /></button>
                </div>

                {!successMsg ? (
                    <form onSubmit={handleSubmit} className="space-y-4">
                        {error && <div className="p-3 bg-red-500/10 text-red-400 text-sm rounded-lg">{error}</div>}

                        <div>
                            <label className="block text-xs uppercase text-white/40 mb-1">Email Address</label>
                            <input
                                type="email"
                                required
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none"
                                placeholder="member@example.com"
                            />
                        </div>

                        <div>
                            <label className="block text-xs uppercase text-white/40 mb-1">Full Name</label>
                            <input
                                type="text"
                                value={name}
                                onChange={e => setName(e.target.value)}
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none"
                                placeholder="e.g. John Doe"
                            />
                        </div>

                        <div>
                            <label className="block text-xs uppercase text-white/40 mb-1">Set Password</label>
                            <div className="relative">
                                <Key className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-white/30" />
                                <input
                                    type="text"
                                    required
                                    value={password}
                                    onChange={e => setPassword(e.target.value)}
                                    className="w-full bg-white/5 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-white focus:border-teal/50 outline-none font-mono"
                                    placeholder="Enter initial password"
                                    minLength={6}
                                />
                            </div>
                            <p className="text-[10px] text-white/30 mt-1">Share this password with the member.</p>
                        </div>

                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors"
                        >
                            {loading ? <Loader2 className="animate-spin" /> : <UserPlus className="w-5 h-5" />}
                            Create & Add Member
                        </button>
                    </form>
                ) : (
                    <div className="text-center py-6">
                        <div className="w-12 h-12 bg-teal/20 text-teal rounded-full flex items-center justify-center mx-auto mb-4">
                            <UserPlus className="w-6 h-6" />
                        </div>
                        <h4 className="text-white font-bold mb-2">Success!</h4>
                        <p className="text-white/60 mb-4">{successMsg}</p>
                    </div>
                )}
            </motion.div>
        </div>
    );
}


function UpdatePasswordModal({ isOpen, onClose, teamId, memberId, memberName }) {
    const [newPassword, setNewPassword] = useState("");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [success, setSuccess] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");
        setLoading(true);

        try {
            const result = await updateMemberPassword(teamId, memberId, newPassword);

            if (!result.success) {
                throw new Error(result.error || "Failed to update password");
            }

            setSuccess(true);
            setTimeout(() => {
                onClose();
                setSuccess(false);
                setNewPassword("");
            }, 1500);
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="bg-gray-900 border border-white/10 rounded-2xl w-full max-w-md p-6"
            >
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-serif font-bold text-white">Update Credentials</h3>
                    <button onClick={onClose}><X className="text-white/50 hover:text-white" /></button>
                </div>

                {!success ? (
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="p-3 bg-blue-500/10 border border-blue-500/20 rounded-lg text-sm text-blue-300">
                            Updating password for <span className="font-bold text-white">{memberName || "User"}</span>.
                        </div>

                        {error && <div className="p-3 bg-red-500/10 text-red-400 text-sm rounded-lg">{error}</div>}

                        <div>
                            <label className="block text-xs uppercase text-white/40 mb-1">New Password</label>
                            <input
                                type="text"
                                required
                                value={newPassword}
                                onChange={e => setNewPassword(e.target.value)}
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none font-mono"
                                placeholder="Enter new password"
                                minLength={6}
                            />
                        </div>

                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors"
                        >
                            {loading ? <Loader2 className="animate-spin" /> : <Key className="w-5 h-5" />}
                            Update Password
                        </button>
                    </form>
                ) : (
                    <div className="text-center py-6">
                        <div className="w-12 h-12 bg-teal/20 text-teal rounded-full flex items-center justify-center mx-auto mb-4">
                            <Key className="w-6 h-6" />
                        </div>
                        <h4 className="text-white font-bold mb-2">Password Updated!</h4>
                        <p className="text-white/60">The user can now log in with the new credentials.</p>
                    </div>
                )}
            </motion.div>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import NetworkSidebar from "@/components/network/Sidebar";
import { createClient } from "@/lib/supabase/client";
import {
    Plus,
    Search,
    Trash2,
    Key,
    Shield,
    Users,
    Loader2,
    X,
    Mail,
    User,
    ChevronDown,
    AlertCircle
} from "lucide-react";
import ConfirmationModal from "@/components/ui/ConfirmationModal";

const CORE_COUNCIL_ROLES = [
    { value: "president", label: "President" },
    { value: "vice_president", label: "Vice President" },
    { value: "general_secretary", label: "General Secretary" },
    { value: "joint_secretary", label: "Joint Secretary" },
    { value: "faculty", label: "Faculty Advisor" }
];

const TEAM_ROLES = [
    { value: "head", label: "Head" },
    { value: "member", label: "Member" }
];

export default function PersonnelPage() {
    const { profile, canManageMembers, isPresident } = useAuth();
    const [members, setMembers] = useState([]);
    const [teams, setTeams] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const [filterRole, setFilterRole] = useState("all");
    const [showAddModal, setShowAddModal] = useState(false);
    const [showCredentialsModal, setShowCredentialsModal] = useState(null);

    // Global Alert/Confirm State
    const [statusModal, setStatusModal] = useState({
        isOpen: false,
        type: "confirm",
        title: "",
        message: "",
        onConfirm: null
    });

    const showAlert = (title, message, type = "success") => {
        setStatusModal({ isOpen: true, title, message, type, onConfirm: null });
    };

    const showConfirm = (title, message, onConfirm, isDangerous = false) => {
        setStatusModal({ isOpen: true, title, message, type: "confirm", onConfirm, isDangerous });
    };

    const supabase = createClient();

    const fetchData = useCallback(async () => {
        if (!profile?.id) return;
        setLoading(true);
        try {
            // Fetch all profiles with their team memberships
            const { data: profilesData, error: profilesError } = await supabase
                .from("profiles")
                .select(`
                    *,
                    team_members (
                        id,
                        role,
                        team_id,
                        teams:team_id (
                            id,
                            name,
                            type
                        )
                    )
                `)
                .order("created_at", { ascending: false });

            if (profilesError) throw profilesError;
            setMembers(profilesData || []);

            // Fetch teams for the dropdown
            const { data: teamsData, error: teamsError } = await supabase
                .from("teams")
                .select("id, name, type")
                .order("name");

            if (teamsError) throw teamsError;
            setTeams(teamsData || []);
        } catch (error) {
            console.error("Error fetching data:", error);
        } finally {
            setLoading(false);
        }
    }, [profile?.id, supabase]);

    useEffect(() => {
        fetchData();

        // Realtime subscription
        const profilesChannel = supabase
            .channel("profiles-changes")
            .on("postgres_changes", { event: "*", schema: "public", table: "profiles" }, fetchData)
            .subscribe();

        const membersChannel = supabase
            .channel("team-members-changes")
            .on("postgres_changes", { event: "*", schema: "public", table: "team_members" }, fetchData)
            .subscribe();

        return () => {
            supabase.removeChannel(profilesChannel);
            supabase.removeChannel(membersChannel);
        };
    }, [fetchData, supabase]);

    const handleDeleteMember = async (memberId, memberEmail) => {
        showConfirm(
            "Remove Member",
            `Are you sure you want to remove "${memberEmail}" from the system? This will also delete their Supabase Auth account.`,
            async () => {
                try {
                    const res = await fetch("/api/admin/delete-user", {
                        method: "DELETE",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ userId: memberId })
                    });

                    if (!res.ok) {
                        const data = await res.json();
                        throw new Error(data.error || "Failed to delete user");
                    }

                    fetchData();
                    showAlert("Removed", "Member has been successfully removed from the system.", "success");
                } catch (error) {
                    console.error("Error deleting member:", error);
                    showAlert("Error", error.message, "error");
                }
            },
            true
        );
    };

    const filteredMembers = members.filter(member => {
        const matchesSearch =
            member.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
            member.email?.toLowerCase().includes(searchQuery.toLowerCase());

        const matchesRole = filterRole === "all" || member.role === filterRole;

        return matchesSearch && matchesRole;
    });

    const getRoleBadge = (role) => {
        const colors = {
            president: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
            vice_president: "bg-purple-500/20 text-purple-400 border-purple-500/30",
            general_secretary: "bg-blue-500/20 text-blue-400 border-blue-500/30",
            joint_secretary: "bg-orange-500/20 text-orange-400 border-orange-500/30",
            faculty: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30",
            head: "bg-teal/20 text-teal border-teal/30",
            member: "bg-white/10 text-white/60 border-white/20"
        };

        return colors[role] || colors.member;
    };

    const formatRole = (role) => {
        return role.split("_").map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(" ");
    };

    if (!canManageMembers() && !isPresident()) {
        return (
            <div className="flex min-h-screen">
                <NetworkSidebar />
                <main className="flex-1 p-10 flex items-center justify-center">
                    <div className="text-center">
                        <Shield className="w-16 h-16 text-red-400/50 mx-auto mb-4" />
                        <h1 className="text-2xl font-serif text-white mb-2">Access Denied</h1>
                        <p className="text-white/50">You don&apos;t have permission to view personnel.</p>
                    </div>
                </main>
            </div>
        );
    }

    return (
        <div className="flex min-h-screen">
            <NetworkSidebar />

            <main className="flex-1 p-6 lg:p-10 pt-24 lg:pt-10 overflow-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8"
                >
                    <div>
                        <h1 className="text-3xl lg:text-4xl font-serif font-bold text-white mb-2">
                            Personnel
                        </h1>
                        <p className="text-white/50">
                            Manage all club members and their roles
                        </p>
                    </div>

                    {canManageMembers() && (
                        <button
                            onClick={() => setShowAddModal(true)}
                            className="flex items-center gap-2 px-5 py-3 bg-teal text-black font-bold rounded-xl hover:bg-teal/80 transition-colors"
                        >
                            <Plus className="w-5 h-5" />
                            Add Member
                        </button>
                    )}
                </motion.div>

                {/* Filters */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="flex flex-col md:flex-row gap-4 mb-6"
                >
                    {/* Search */}
                    <div className="relative flex-1">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/30" />
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            placeholder="Search by name or email..."
                            className="w-full bg-white/5 border border-white/10 rounded-xl pl-12 pr-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                        />
                    </div>

                    {/* Role Filter */}
                    <div className="relative">
                        <select
                            value={filterRole}
                            onChange={(e) => setFilterRole(e.target.value)}
                            className="appearance-none bg-gray-800 border border-white/10 rounded-xl px-4 py-3 pr-10 text-white focus:border-teal/50 outline-none min-w-[180px]"
                            style={{ colorScheme: 'dark' }}
                        >
                            <option value="all" className="bg-gray-800 text-white">All Roles</option>
                            <optgroup label="Core Council" className="bg-gray-800 text-white">
                                {CORE_COUNCIL_ROLES.map(role => (
                                    <option key={role.value} value={role.value} className="bg-gray-800 text-white">{role.label}</option>
                                ))}
                            </optgroup>
                            <optgroup label="Team Roles" className="bg-gray-800 text-white">
                                {TEAM_ROLES.map(role => (
                                    <option key={role.value} value={role.value} className="bg-gray-800 text-white">{role.label}</option>
                                ))}
                            </optgroup>
                        </select>
                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/30 pointer-events-none" />
                    </div>
                </motion.div>

                {/* Members Table */}
                {loading ? (
                    <div className="flex items-center justify-center py-20">
                        <Loader2 className="w-10 h-10 text-teal animate-spin" />
                    </div>
                ) : filteredMembers.length === 0 ? (
                    <div className="text-center py-20">
                        <Users className="w-16 h-16 text-white/10 mx-auto mb-4" />
                        <h3 className="text-xl text-white/50 mb-2">No Members Found</h3>
                        <p className="text-white/30">Try adjusting your search or filters</p>
                    </div>
                ) : (
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.2 }}
                        className="bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-2xl overflow-hidden"
                    >
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead>
                                    <tr className="border-b border-white/5">
                                        <th className="text-left px-6 py-4 text-[10px] uppercase tracking-widest text-white/40 font-mono">Member</th>
                                        <th className="text-left px-6 py-4 text-[10px] uppercase tracking-widest text-white/40 font-mono">Role</th>
                                        <th className="text-left px-6 py-4 text-[10px] uppercase tracking-widest text-white/40 font-mono">Team(s)</th>
                                        {canManageMembers() && (
                                            <th className="text-right px-6 py-4 text-[10px] uppercase tracking-widest text-white/40 font-mono">Actions</th>
                                        )}
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredMembers.map((member, index) => (
                                        <tr
                                            key={member.id}
                                            className="border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors"
                                        >
                                            <td className="px-6 py-4">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-10 h-10 bg-gradient-to-br from-teal/20 to-purple-500/20 rounded-full flex items-center justify-center">
                                                        <span className="text-white font-bold text-sm">
                                                            {member.full_name?.[0] || member.email?.[0] || "?"}
                                                        </span>
                                                    </div>
                                                    <div>
                                                        <p className="text-white font-medium">{member.full_name || "Unnamed"}</p>
                                                        <p className="text-white/40 text-sm">{member.email}</p>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className={`inline-block px-2 py-1 text-[10px] uppercase tracking-widest rounded-full border ${getRoleBadge(member.role)}`}>
                                                    {formatRole(member.role)}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex flex-wrap gap-1">
                                                    {member.team_members?.length > 0 ? (
                                                        member.team_members.map(tm => (
                                                            <span
                                                                key={tm.id}
                                                                className={`inline-block px-2 py-0.5 text-xs rounded ${tm.teams?.type === "fest"
                                                                    ? "bg-purple-500/20 text-purple-400"
                                                                    : "bg-teal/20 text-teal"
                                                                    }`}
                                                            >
                                                                {tm.teams?.name} {tm.role === "head" && "(Head)"}
                                                            </span>
                                                        ))
                                                    ) : (
                                                        <span className="text-white/30 text-sm">ÔÇö</span>
                                                    )}
                                                </div>
                                            </td>
                                            {canManageMembers() && (
                                                <td className="px-6 py-4">
                                                    <div className="flex items-center justify-end gap-2">
                                                        <button
                                                            onClick={() => setShowCredentialsModal(member)}
                                                            className="p-2 text-white/40 hover:text-teal hover:bg-teal/10 rounded-lg transition-colors"
                                                            title="Reset Password"
                                                        >
                                                            <Key className="w-4 h-4" />
                                                        </button>
                                                        {member.id !== profile?.id && (
                                                            <button
                                                                onClick={() => handleDeleteMember(member.id, member.email)}
                                                                className="p-2 text-white/40 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                                                                title="Remove Member"
                                                            >
                                                                <Trash2 className="w-4 h-4" />
                                                            </button>
                                                        )}
                                                    </div>
                                                </td>
                                            )}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </motion.div>
                )}
            </main>

            {/* Add Member Modal */}
            <AnimatePresence>
                {showAddModal && (
                    <AddMemberModal
                        teams={teams}
                        onClose={() => setShowAddModal(false)}
                        onSuccess={() => {
                            setShowAddModal(false);
                            fetchData();
                        }}
                    />
                )}
            </AnimatePresence>

            {/* Credentials Modal */}
            <AnimatePresence>
                {showCredentialsModal && (
                    <CredentialsModal
                        member={showCredentialsModal}
                        onClose={() => setShowCredentialsModal(null)}
                    />
                )}
            </AnimatePresence>

            {/* Global Status/Confirmation Modal */}
            <ConfirmationModal
                isOpen={statusModal.isOpen}
                type={statusModal.type}
                title={statusModal.title}
                message={statusModal.message}
                isDangerous={statusModal.isDangerous}
                onClose={() => setStatusModal(prev => ({ ...prev, isOpen: false }))}
                onConfirm={statusModal.onConfirm ? () => {
                    statusModal.onConfirm();
                    setStatusModal(prev => ({ ...prev, isOpen: false }));
                } : null}
            />
        </div>
    );
}

function AddMemberModal({ teams, onClose, onSuccess }) {
    const { profile } = useAuth();
    const [email, setEmail] = useState("");
    const [fullName, setFullName] = useState("");
    const [role, setRole] = useState("member");
    const [teamId, setTeamId] = useState("");
    const [teamRole, setTeamRole] = useState("member");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");

    const isCoreCouncilRole = CORE_COUNCIL_ROLES.some(r => r.value === role);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");

        if (!email.trim()) {
            setError("Email is required");
            return;
        }

        if (!isCoreCouncilRole && !teamId) {
            setError("Please select a team for this member");
            return;
        }

        setSaving(true);

        try {
            const res = await fetch("/api/admin/create-user", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    email: email.trim().toLowerCase(),
                    fullName: fullName.trim(),
                    role,
                    teamId: isCoreCouncilRole ? null : teamId,
                    teamRole: isCoreCouncilRole ? null : teamRole
                })
            });

            const data = await res.json();

            if (!res.ok) {
                throw new Error(data.error || "Failed to create user");
            }

            onSuccess();
        } catch (err) {
            setError(err.message);
        } finally {
            setSaving(false);
        }
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        >
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-gray-900/95 backdrop-blur-xl border border-white/10 rounded-2xl w-full max-w-md overflow-hidden max-h-[90vh] overflow-y-auto"
            >
                {/* Modal Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-white/5 sticky top-0 bg-gray-900/95 backdrop-blur-xl">
                    <h2 className="text-xl font-serif font-bold text-white">Add New Member</h2>
                    <button onClick={onClose} className="text-white/50 hover:text-white">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Modal Body */}
                <form onSubmit={handleSubmit} className="p-6 space-y-5">
                    {error && (
                        <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400 text-sm flex items-center gap-2">
                            <AlertCircle className="w-4 h-4 flex-shrink-0" />
                            {error}
                        </div>
                    )}

                    {/* Email */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Email Address *
                        </label>
                        <div className="relative">
                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/30" />
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                placeholder="member@cbit.ac.in"
                                required
                                className="w-full bg-white/5 border border-white/10 rounded-xl pl-12 pr-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                            />
                        </div>
                    </div>

                    {/* Full Name */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Full Name
                        </label>
                        <div className="relative">
                            <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/30" />
                            <input
                                type="text"
                                value={fullName}
                                onChange={(e) => setFullName(e.target.value)}
                                placeholder="John Doe"
                                className="w-full bg-white/5 border border-white/10 rounded-xl pl-12 pr-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                            />
                        </div>
                    </div>

                    {/* Member Type Toggle */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Member Type *
                        </label>
                        <div className="grid grid-cols-2 gap-3">
                            <button
                                type="button"
                                onClick={() => setRole("member")}
                                className={`px-4 py-3 rounded-xl border transition-all ${!isCoreCouncilRole
                                    ? "bg-teal/10 border-teal/50 text-teal"
                                    : "bg-white/5 border-white/10 text-white/50"
                                    }`}
                            >
                                Team Member
                            </button>
                            <button
                                type="button"
                                onClick={() => setRole("president")}
                                className={`px-4 py-3 rounded-xl border transition-all ${isCoreCouncilRole
                                    ? "bg-purple-500/10 border-purple-500/50 text-purple-400"
                                    : "bg-white/5 border-white/10 text-white/50"
                                    }`}
                            >
                                Core Council
                            </button>
                        </div>
                    </div>

                    {/* Core Council Role Selection */}
                    {isCoreCouncilRole && (
                        <div className="space-y-2">
                            <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                                Council Position *
                            </label>
                            <select
                                value={role}
                                onChange={(e) => setRole(e.target.value)}
                                className="w-full appearance-none bg-gray-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none"
                                style={{ colorScheme: 'dark' }}
                            >
                                {CORE_COUNCIL_ROLES.map(r => (
                                    <option key={r.value} value={r.value} className="bg-gray-800 text-white">{r.label}</option>
                                ))}
                            </select>
                        </div>
                    )}

                    {/* Team Selection (Only for Team Members) */}
                    {!isCoreCouncilRole && (
                        <>
                            <div className="space-y-2">
                                <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                                    Assign to Team *
                                </label>
                                <select
                                    value={teamId}
                                    onChange={(e) => setTeamId(e.target.value)}
                                    required
                                    className="w-full appearance-none bg-gray-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none"
                                    style={{ colorScheme: 'dark' }}
                                >
                                    <option value="" className="bg-gray-800 text-white/50">Select a team...</option>
                                    {teams.map(team => (
                                        <option key={team.id} value={team.id} className="bg-gray-800 text-white">
                                            {team.name} ({team.type === "fest" ? "Fest" : "General"})
                                        </option>
                                    ))}
                                </select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                                    Role in Team
                                </label>
                                <div className="grid grid-cols-2 gap-3">
                                    <button
                                        type="button"
                                        onClick={() => setTeamRole("member")}
                                        className={`px-4 py-3 rounded-xl border transition-all ${teamRole === "member"
                                            ? "bg-teal/10 border-teal/50 text-teal"
                                            : "bg-white/5 border-white/10 text-white/50"
                                            }`}
                                    >
                                        Member
                                    </button>
                                    <button
                                        type="button"
                                        onClick={() => setTeamRole("head")}
                                        className={`px-4 py-3 rounded-xl border transition-all ${teamRole === "head"
                                            ? "bg-yellow-500/10 border-yellow-500/50 text-yellow-400"
                                            : "bg-white/5 border-white/10 text-white/50"
                                            }`}
                                    >
                                        Head
                                    </button>
                                </div>
                            </div>
                        </>
                    )}

                    <p className="text-white/30 text-xs">
                        A temporary password will be generated. You can share it with the member or reset it later.
                    </p>

                    {/* Submit */}
                    <button
                        type="submit"
                        disabled={saving}
                        className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors disabled:opacity-50"
                    >
                        {saving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Creating...
                            </>
                        ) : (
                            <>
                                <Plus className="w-5 h-5" />
                                Add Member
                            </>
                        )}
                    </button>
                </form>
            </motion.div>
        </motion.div>
    );
}

function CredentialsModal({ member, onClose }) {
    const [newPassword, setNewPassword] = useState("");
    const [saving, setSaving] = useState(false);
    const [success, setSuccess] = useState(false);
    const [error, setError] = useState("");

    const handleResetPassword = async () => {
        if (!newPassword || newPassword.length < 6) {
            setError("Password must be at least 6 characters");
            return;
        }

        setSaving(true);
        setError("");

        try {
            const res = await fetch("/api/admin/update-credentials", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    userId: member.id,
                    newPassword
                })
            });

            const data = await res.json();

            if (!res.ok) {
                throw new Error(data.error || "Failed to update password");
            }

            setSuccess(true);
        } catch (err) {
            setError(err.message);
        } finally {
            setSaving(false);
        }
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        >
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-gray-900/95 backdrop-blur-xl border border-white/10 rounded-2xl w-full max-w-md overflow-hidden"
            >
                {/* Modal Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-white/5">
                    <h2 className="text-xl font-serif font-bold text-white">Reset Password</h2>
                    <button onClick={onClose} className="text-white/50 hover:text-white">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Modal Body */}
                <div className="p-6 space-y-5">
                    <div className="flex items-center gap-3 p-4 bg-white/5 rounded-xl">
                        <div className="w-10 h-10 bg-gradient-to-br from-teal/20 to-purple-500/20 rounded-full flex items-center justify-center">
                            <span className="text-white font-bold text-sm">
                                {member.full_name?.[0] || member.email?.[0] || "?"}
                            </span>
                        </div>
                        <div>
                            <p className="text-white font-medium">{member.full_name || "Unnamed"}</p>
                            <p className="text-white/40 text-sm">{member.email}</p>
                        </div>
                    </div>

                    {success ? (
                        <div className="text-center py-4">
                            <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Key className="w-8 h-8 text-green-400" />
                            </div>
                            <h3 className="text-lg text-white font-medium mb-2">Password Updated!</h3>
                            <p className="text-white/50 text-sm">The new password has been set successfully.</p>
                        </div>
                    ) : (
                        <>
                            {error && (
                                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400 text-sm">
                                    {error}
                                </div>
                            )}

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                                    New Password
                                </label>
                                <input
                                    type="text"
                                    value={newPassword}
                                    onChange={(e) => setNewPassword(e.target.value)}
                                    placeholder="Enter new password"
                                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                                />
                                <p className="text-white/30 text-xs">Minimum 6 characters</p>
                            </div>

                            <button
                                onClick={handleResetPassword}
                                disabled={saving}
                                className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors disabled:opacity-50"
                            >
                                {saving ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Updating...
                                    </>
                                ) : (
                                    <>
                                        <Key className="w-5 h-5" />
                                        Reset Password
                                    </>
                                )}
                            </button>
                        </>
                    )}
                </div>
            </motion.div>
        </motion.div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import NetworkSidebar from "@/components/network/Sidebar";
import { createClient } from "@/lib/supabase/client";
import {
    FolderOpen,
    Plus,
    Link as LinkIcon,
    FileText,
    FileCode,
    ExternalLink,
    Trash2,
    Loader2,
    X,
    Search,
    Check
} from "lucide-react";
import ConfirmationModal from "@/components/ui/ConfirmationModal";

const TYPE_CONFIG = {
    link: { label: "Link", icon: LinkIcon, color: "bg-blue-500/20 text-blue-400 border-blue-500/30" },
    file: { label: "File", icon: FileText, color: "bg-green-500/20 text-green-400 border-green-500/30" },
    template: { label: "Template", icon: FileCode, color: "bg-purple-500/20 text-purple-400 border-purple-500/30" }
};

export default function ResourcesPage() {
    const { profile, isPresident } = useAuth();
    const [resources, setResources] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [filterType, setFilterType] = useState("all");

    // Global Alert/Confirm State
    const [statusModal, setStatusModal] = useState({
        isOpen: false,
        type: "confirm",
        title: "",
        message: "",
        onConfirm: null
    });

    const showAlert = (title, message, type = "success") => {
        setStatusModal({ isOpen: true, title, message, type, onConfirm: null });
    };

    const showConfirm = (title, message, onConfirm, isDangerous = false) => {
        setStatusModal({ isOpen: true, title, message, type: "confirm", onConfirm, isDangerous });
    };

    const supabase = createClient();

    useEffect(() => {
        fetchResources();

        // Realtime subscription
        const channel = supabase
            .channel("resources-changes")
            .on("postgres_changes", { event: "*", schema: "public", table: "resources" }, fetchResources)
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [profile]);

    const fetchResources = async () => {
        if (!profile?.id) return;
        try {
            const { data, error } = await supabase
                .from("resources")
                .select(`
                    *,
                    creator:created_by (full_name, email)
                `)
                .order("created_at", { ascending: false });

            if (error) throw error;
            setResources(data || []);
        } catch (error) {
            console.error("Error fetching resources:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (resourceId) => {
        showConfirm(
            "Delete Resource",
            "Are you sure you want to delete this resource? This action cannot be undone.",
            async () => {
                try {
                    const { error } = await supabase.from("resources").delete().eq("id", resourceId);
                    if (error) throw error;
                    fetchResources();
                    showAlert("Deleted", "Resource has been removed successfully.", "success");
                } catch (error) {
                    console.error("Error deleting resource:", error);
                    showAlert("Error", "Failed to delete resource.", "error");
                }
            },
            true
        );
    };

    const filteredResources = resources.filter(resource => {
        const matchesSearch = resource.title?.toLowerCase().includes(searchQuery.toLowerCase()) ||
            resource.description?.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesType = filterType === "all" || resource.type === filterType;
        return matchesSearch && matchesType;
    });

    return (
        <div className="flex min-h-screen">
            <NetworkSidebar />

            <main className="flex-1 p-6 lg:p-10 pt-24 lg:pt-10 overflow-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10"
                >
                    <div>
                        <h1 className="text-3xl lg:text-4xl font-serif font-bold text-white mb-2">
                            Resources
                        </h1>
                        <p className="text-white/50">
                            Shared documents, templates, and important links
                        </p>
                    </div>

                    {isPresident() && (
                        <button
                            onClick={() => setShowModal(true)}
                            className="flex items-center gap-2 px-5 py-3 bg-teal text-black font-bold rounded-xl hover:bg-teal/80 transition-colors"
                        >
                            <Plus className="w-5 h-5" />
                            Add Resource
                        </button>
                    )}
                </motion.div>

                {/* Filters */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="flex flex-col md:flex-row gap-4 mb-6"
                >
                    {/* Search */}
                    <div className="relative flex-1">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/30" />
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            placeholder="Search resources..."
                            className="w-full bg-white/5 border border-white/10 rounded-xl pl-12 pr-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                        />
                    </div>

                    {/* Type Filter */}
                    <div className="flex gap-2">
                        <button
                            onClick={() => setFilterType("all")}
                            className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${filterType === "all"
                                ? "bg-white/10 text-white"
                                : "text-white/50 hover:text-white"
                                }`}
                        >
                            All
                        </button>
                        {Object.entries(TYPE_CONFIG).map(([key, config]) => (
                            <button
                                key={key}
                                onClick={() => setFilterType(key)}
                                className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${filterType === key
                                    ? config.color
                                    : "text-white/50 hover:text-white"
                                    }`}
                            >
                                {config.label}
                            </button>
                        ))}
                    </div>
                </motion.div>

                {/* Resources Grid */}
                {loading ? (
                    <div className="flex items-center justify-center py-20">
                        <Loader2 className="w-10 h-10 text-teal animate-spin" />
                    </div>
                ) : filteredResources.length === 0 ? (
                    <div className="text-center py-20">
                        <FolderOpen className="w-16 h-16 text-white/10 mx-auto mb-4" />
                        <h3 className="text-xl text-white/50 mb-2">No Resources Found</h3>
                        <p className="text-white/30">
                            {searchQuery || filterType !== "all" ? "Try adjusting your search or filters" : "Add your first resource"}
                        </p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {filteredResources.map((resource, index) => {
                            const typeConfig = TYPE_CONFIG[resource.type] || TYPE_CONFIG.link;
                            const Icon = typeConfig.icon;

                            return (
                                <motion.div
                                    key={resource.id}
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: index * 0.03 }}
                                    className="bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-2xl p-5 hover:border-teal/20 transition-colors group"
                                >
                                    <div className="flex items-start justify-between mb-3">
                                        <div className={`p-2 rounded-lg ${typeConfig.color.split(' ')[0]}`}>
                                            <Icon className={`w-5 h-5 ${typeConfig.color.split(' ')[1]}`} />
                                        </div>
                                        <span className={`px-2 py-0.5 text-[10px] uppercase tracking-widest rounded-full border ${typeConfig.color}`}>
                                            {typeConfig.label}
                                        </span>
                                    </div>

                                    <h3 className="text-white font-medium mb-2 line-clamp-1">{resource.title}</h3>
                                    {resource.description && (
                                        <p className="text-white/40 text-sm mb-4 line-clamp-2">{resource.description}</p>
                                    )}

                                    <div className="flex items-center justify-between mt-auto pt-3 border-t border-white/5">
                                        {resource.url && (
                                            <a
                                                href={resource.url}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="flex items-center gap-1.5 text-teal text-sm hover:underline"
                                            >
                                                <ExternalLink className="w-4 h-4" />
                                                Open
                                            </a>
                                        )}

                                        {isPresident() && (
                                            <button
                                                onClick={() => handleDelete(resource.id)}
                                                className="p-1.5 text-white/30 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        )}
                                    </div>
                                </motion.div>
                            );
                        })}
                    </div>
                )}
            </main>

            {/* Add Resource Modal */}
            <AnimatePresence>
                {showModal && (
                    <AddResourceModal
                        onClose={() => setShowModal(false)}
                        onSuccess={() => {
                            setShowModal(false);
                            fetchResources();
                        }}
                    />
                )}
            </AnimatePresence>
            {/* Global Status/Confirmation Modal */}
            <ConfirmationModal
                isOpen={statusModal.isOpen}
                type={statusModal.type}
                title={statusModal.title}
                message={statusModal.message}
                isDangerous={statusModal.isDangerous}
                onClose={() => setStatusModal(prev => ({ ...prev, isOpen: false }))}
                onConfirm={statusModal.onConfirm ? () => {
                    statusModal.onConfirm();
                    setStatusModal(prev => ({ ...prev, isOpen: false }));
                } : null}
            />
        </div>
    );
}

function AddResourceModal({ onClose, onSuccess }) {
    const { profile } = useAuth();
    const [title, setTitle] = useState("");
    const [description, setDescription] = useState("");
    const [type, setType] = useState("link");
    const [url, setUrl] = useState("");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const supabase = createClient();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");

        if (!title.trim()) {
            setError("Title is required");
            return;
        }

        if (!url.trim()) {
            setError("URL is required");
            return;
        }

        setSaving(true);

        try {
            const { error: insertError } = await supabase
                .from("resources")
                .insert({
                    title: title.trim(),
                    description: description.trim() || null,
                    type,
                    url: url.trim(),
                    created_by: profile.id
                });

            if (insertError) throw insertError;
            onSuccess();
        } catch (err) {
            console.error("Error creating resource:", err);
            setError(err.message || "Failed to create resource");
        } finally {
            setSaving(false);
        }
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        >
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-gray-900/95 backdrop-blur-xl border border-white/10 rounded-2xl w-full max-w-md overflow-hidden"
            >
                {/* Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-white/5">
                    <h2 className="text-xl font-serif font-bold text-white">Add Resource</h2>
                    <button onClick={onClose} className="text-white/50 hover:text-white">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Body */}
                <form onSubmit={handleSubmit} className="p-6 space-y-5">
                    {error && (
                        <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400 text-sm">
                            {error}
                        </div>
                    )}

                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Title *
                        </label>
                        <input
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            placeholder="Resource title"
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Description
                        </label>
                        <textarea
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Brief description..."
                            rows={2}
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none resize-none"
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Type
                        </label>
                        <div className="grid grid-cols-3 gap-2">
                            {Object.entries(TYPE_CONFIG).map(([key, config]) => {
                                const Icon = config.icon;
                                return (
                                    <button
                                        key={key}
                                        type="button"
                                        onClick={() => setType(key)}
                                        className={`flex items-center justify-center gap-2 px-3 py-2.5 rounded-xl border transition-all text-sm ${type === key
                                            ? config.color
                                            : "bg-white/5 border-white/10 text-white/50"
                                            }`}
                                    >
                                        <Icon className="w-4 h-4" />
                                        {config.label}
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            URL *
                        </label>
                        <input
                            type="url"
                            value={url}
                            onChange={(e) => setUrl(e.target.value)}
                            placeholder="https://..."
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                        />
                    </div>

                    <button
                        type="submit"
                        disabled={saving}
                        className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors disabled:opacity-50"
                    >
                        {saving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Adding...
                            </>
                        ) : (
                            "Add Resource"
                        )}
                    </button>
                </form>
            </motion.div>
        </motion.div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import NetworkSidebar from "@/components/network/Sidebar";
import { createClient } from "@/lib/supabase/client";
import { Settings, Shield, Users, ToggleLeft, ToggleRight, Loader2, CheckCircle, AlertCircle } from "lucide-react";

export default function SettingsPage() {
    const { profile, isPresident } = useAuth();
    const [delegatedUsers, setDelegatedUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(null);
    const [message, setMessage] = useState(null);
    const supabase = createClient();

    // Fetch VP, GS, JS and their permission states
    useEffect(() => {
        const fetchDelegatedUsers = async () => {
            try {
                // Fetch core council members who can receive delegated permissions
                const { data: coreUsers, error: usersError } = await supabase
                    .from("profiles")
                    .select("id, email, full_name, role")
                    .in("role", ["vice_president", "general_secretary", "joint_secretary"]);

                if (usersError) throw usersError;

                // Fetch existing permissions
                const { data: permissions, error: permError } = await supabase
                    .from("delegated_permissions")
                    .select("*");

                if (permError && permError.code !== "PGRST116") throw permError;

                // Merge data
                const merged = (coreUsers || []).map(user => {
                    const perm = permissions?.find(p => p.user_id === user.id);
                    return {
                        ...user,
                        can_manage_teams: perm?.can_manage_teams || false,
                        can_manage_members: perm?.can_manage_members || false,
                        has_permission_row: !!perm,
                        permission_id: perm?.id
                    };
                });

                setDelegatedUsers(merged);
            } catch (error) {
                console.error("Error fetching delegated users:", error);
            } finally {
                setLoading(false);
            }
        };

        if (isPresident()) {
            fetchDelegatedUsers();
        } else {
            setLoading(false);
        }
    }, [isPresident]);

    const togglePermission = async (userId, permissionType, currentValue) => {
        setSaving(userId);
        setMessage(null);

        try {
            const user = delegatedUsers.find(u => u.id === userId);

            if (user.has_permission_row) {
                // Update existing row
                const { error } = await supabase
                    .from("delegated_permissions")
                    .update({ [permissionType]: !currentValue })
                    .eq("user_id", userId);

                if (error) throw error;
            } else {
                // Insert new row
                const { error } = await supabase
                    .from("delegated_permissions")
                    .insert({
                        user_id: userId,
                        [permissionType]: true,
                        granted_by: profile.id
                    });

                if (error) throw error;
            }

            // Update local state
            setDelegatedUsers(prev =>
                prev.map(u => {
                    if (u.id === userId) {
                        return {
                            ...u,
                            [permissionType]: !currentValue,
                            has_permission_row: true
                        };
                    }
                    return u;
                })
            );

            setMessage({ type: "success", text: "Permission updated successfully" });
        } catch (error) {
            console.error("Error updating permission:", error);
            setMessage({ type: "error", text: "Failed to update permission" });
        } finally {
            setSaving(null);
        }
    };

    if (!isPresident()) {
        return (
            <div className="flex min-h-screen">
                <NetworkSidebar />
                <main className="flex-1 p-10 flex items-center justify-center">
                    <div className="text-center">
                        <Shield className="w-16 h-16 text-red-400/50 mx-auto mb-4" />
                        <h1 className="text-2xl font-serif text-white mb-2">Access Denied</h1>
                        <p className="text-white/50">Only the President can access settings.</p>
                    </div>
                </main>
            </div>
        );
    }

    const getRoleBadgeColor = (role) => {
        switch (role) {
            case "vice_president": return "bg-purple-500/20 text-purple-400 border-purple-500/30";
            case "general_secretary": return "bg-blue-500/20 text-blue-400 border-blue-500/30";
            case "joint_secretary": return "bg-orange-500/20 text-orange-400 border-orange-500/30";
            default: return "bg-white/10 text-white/70 border-white/20";
        }
    };

    const formatRole = (role) => {
        return role.split("_").map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(" ");
    };

    return (
        <div className="flex min-h-screen">
            <NetworkSidebar />

            <main className="flex-1 p-6 lg:p-10 pt-24 lg:pt-10 overflow-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mb-10"
                >
                    <div className="flex items-center gap-3 mb-2">
                        <Settings className="w-8 h-8 text-teal" />
                        <h1 className="text-3xl lg:text-4xl font-serif font-bold text-white">Settings</h1>
                    </div>
                    <p className="text-white/50">Manage system settings and delegated permissions.</p>
                </motion.div>

                {/* Message Toast */}
                {message && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className={`mb-6 p-4 rounded-xl flex items-center gap-3 ${message.type === "success"
                            ? "bg-green-500/10 border border-green-500/20 text-green-400"
                            : "bg-red-500/10 border border-red-500/20 text-red-400"
                            }`}
                    >
                        {message.type === "success" ? <CheckCircle className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
                        {message.text}
                    </motion.div>
                )}

                {/* Delegated Permissions Card */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-2xl overflow-hidden"
                >
                    <div className="px-6 py-4 border-b border-white/5 flex items-center gap-3">
                        <Shield className="w-5 h-5 text-teal" />
                        <h2 className="text-lg font-serif font-bold text-white">Delegated Permissions</h2>
                    </div>

                    <div className="p-6">
                        <p className="text-white/50 text-sm mb-6">
                            Grant VP, GS, or JS the ability to manage teams and members on your behalf.
                        </p>

                        {loading ? (
                            <div className="flex items-center justify-center py-10">
                                <Loader2 className="w-8 h-8 text-teal animate-spin" />
                            </div>
                        ) : delegatedUsers.length === 0 ? (
                            <div className="text-center py-10 text-white/30">
                                <Users className="w-12 h-12 mx-auto mb-2 opacity-50" />
                                <p>No VP, GS, or JS members found.</p>
                                <p className="text-xs mt-1">Add core council members to delegate permissions.</p>
                            </div>
                        ) : (
                            <div className="space-y-4">
                                {delegatedUsers.map(user => (
                                    <div
                                        key={user.id}
                                        className="bg-white/5 border border-white/10 rounded-xl p-4"
                                    >
                                        <div className="flex items-center justify-between mb-4">
                                            <div>
                                                <h3 className="text-white font-medium">{user.full_name || user.email}</h3>
                                                <span className={`inline-block mt-1 px-2 py-0.5 text-[10px] uppercase tracking-widest rounded-full border ${getRoleBadgeColor(user.role)}`}>
                                                    {formatRole(user.role)}
                                                </span>
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            {/* Team Management Toggle */}
                                            <div className="flex items-center justify-between bg-black/20 rounded-lg px-4 py-3">
                                                <div>
                                                    <p className="text-white text-sm font-medium">Manage Teams</p>
                                                    <p className="text-white/40 text-xs">Create, edit, delete teams</p>
                                                </div>
                                                <button
                                                    onClick={() => togglePermission(user.id, "can_manage_teams", user.can_manage_teams)}
                                                    disabled={saving === user.id}
                                                    className="relative"
                                                >
                                                    {saving === user.id ? (
                                                        <Loader2 className="w-8 h-8 text-teal animate-spin" />
                                                    ) : user.can_manage_teams ? (
                                                        <ToggleRight className="w-10 h-10 text-teal" />
                                                    ) : (
                                                        <ToggleLeft className="w-10 h-10 text-white/30" />
                                                    )}
                                                </button>
                                            </div>

                                            {/* Member Management Toggle */}
                                            <div className="flex items-center justify-between bg-black/20 rounded-lg px-4 py-3">
                                                <div>
                                                    <p className="text-white text-sm font-medium">Manage Members</p>
                                                    <p className="text-white/40 text-xs">Add, remove members</p>
                                                </div>
                                                <button
                                                    onClick={() => togglePermission(user.id, "can_manage_members", user.can_manage_members)}
                                                    disabled={saving === user.id}
                                                    className="relative"
                                                >
                                                    {saving === user.id ? (
                                                        <Loader2 className="w-8 h-8 text-teal animate-spin" />
                                                    ) : user.can_manage_members ? (
                                                        <ToggleRight className="w-10 h-10 text-teal" />
                                                    ) : (
                                                        <ToggleLeft className="w-10 h-10 text-white/30" />
                                                    )}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </motion.div>
            </main>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import NetworkSidebar from "@/components/network/Sidebar";
import { createClient } from "@/lib/supabase/client";
import {
    ListTodo,
    Plus,
    Clock,
    CheckCircle,
    AlertCircle,
    Loader2,
    X,
    Calendar,
    Users,
    User,
    Edit3,
    Trash2,
    RefreshCw
} from "lucide-react";
import ConfirmationModal from "@/components/ui/ConfirmationModal";

const STATUS_CONFIG = {
    pending: { label: "Pending", color: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30", icon: Clock },
    approval_start: { label: "Waiting for Approval (Start)", color: "bg-purple-500/20 text-purple-400 border-purple-500/30", icon: Clock },
    in_progress: { label: "In Progress", color: "bg-blue-500/20 text-blue-400 border-blue-500/30", icon: AlertCircle },
    approval_completion: { label: "Waiting for Approval (Completion)", color: "bg-purple-500/20 text-purple-400 border-purple-500/30", icon: CheckCircle },
    completed: { label: "Completed", color: "bg-green-500/20 text-green-400 border-green-500/30", icon: CheckCircle },
    overdue: { label: "Overdue", color: "bg-red-500/20 text-red-400 border-red-500/30", icon: AlertCircle }
};

export default function TasksPage() {
    const { profile, isPresident, isCoreCouncil } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [teams, setTeams] = useState([]);
    const [members, setMembers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [editingTask, setEditingTask] = useState(null);
    const [filterStatus, setFilterStatus] = useState("all");
    const [isHeadOfAny, setIsHeadOfAny] = useState(false);

    // Global Alert/Confirm State
    const [statusModal, setStatusModal] = useState({
        isOpen: false,
        type: "confirm",
        title: "",
        message: "",
        onConfirm: null
    });

    const showAlert = (title, message, type = "success") => {
        setStatusModal({ isOpen: true, title, message, type, onConfirm: null });
    };

    const showConfirm = (title, message, onConfirm, isDangerous = false) => {
        setStatusModal({ isOpen: true, title, message, type: "confirm", onConfirm, isDangerous });
    };

    const supabase = createClient();

    useEffect(() => {
        fetchData();

        // Realtime subscription
        const channel = supabase
            .channel("tasks-changes")
            .on("postgres_changes", { event: "*", schema: "public", table: "tasks" }, fetchData)
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [profile]);

    const fetchData = async () => {
        if (!profile?.id) return;
        setLoading(true);

        try {
            // Fetch tasks visible to the current user
            const { data: tasksData, error: tasksError } = await supabase
                .from("tasks")
                .select(`
                    *,
                    assigned_team:assigned_to_team (id, name, type),
                    assigned_user:assigned_to_user (id, full_name, email),
                    creator:created_by (id, full_name, email)
                `)
                .order("created_at", { ascending: false });

            if (tasksError) throw tasksError;

            // Filter tasks based on visibility
            let visibleTasks = tasksData || [];

            if (!isPresident() && !isCoreCouncil()) {
                // Get user's team IDs and Roles
                const { data: userTeams } = await supabase
                    .from("team_members")
                    .select("team_id, role")
                    .eq("user_id", profile?.id);

                const userTeamIds = userTeams?.map(t => t.team_id) || [];
                const hasHeadRole = userTeams?.some(t => t.role === "head");
                setIsHeadOfAny(hasHeadRole);

                visibleTasks = tasksData?.filter(task => {
                    // Task assigned directly to user
                    if (task.assigned_to_user === profile?.id) return true;
                    // Task assigned to user's team
                    if (task.assigned_to_team && userTeamIds.includes(task.assigned_to_team)) return true;
                    // Task created by user
                    if (task.created_by === profile?.id) return true;
                    return false;
                }) || [];
            }

            setTasks(visibleTasks);

            // Fetch teams and members for the create modal
            const { data: teamsData } = await supabase
                .from("teams")
                .select("id, name, type")
                .order("name");
            setTeams(teamsData || []);

            const { data: membersData } = await supabase
                .from("profiles")
                .select("id, full_name, email, role")
                .order("full_name");
            setMembers(membersData || []);
        } catch (error) {
            console.error("Error fetching tasks:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteTask = async (taskId) => {
        showConfirm(
            "Delete Task",
            "Are you sure you want to delete this task? This action cannot be undone.",
            async () => {
                try {
                    const { error } = await supabase.from("tasks").delete().eq("id", taskId);
                    if (error) throw error;
                    fetchData();
                    showAlert("Deleted", "Task has been removed successfully.", "success");
                } catch (error) {
                    console.error("Error deleting task:", error);
                    showAlert("Error", "Failed to delete task.", "error");
                }
            },
            true
        );
    };

    const handleStatusChange = async (task, newStatus) => {
        try {
            let actualStatus = newStatus;

            // APPROVAL LOGIC
            const isHead = profile?.role === "head" || isPresident();
            const isTeamTask = !!task.assigned_team; // It's a team task if assigned to a team (even if specific user is also set? No, schema is one or other usually, or user belongs to team)
            // Actually, if assigned_to_team is set, it's a team task.

            // If Member (not Head) is updating a Team Task:
            if (isTeamTask && !isHead) {
                if (newStatus === "in_progress" && task.status === "pending") {
                    actualStatus = "approval_start"; // Request Start
                } else if (newStatus === "completed" && task.status === "in_progress") {
                    actualStatus = "approval_completion"; // Request Completion
                } else {
                    // Allow other transitions? e.g. back to pending?
                    // For now, trust the dropdown/buttons.
                }
            }

            const { error } = await supabase
                .from("tasks")
                .update({ status: actualStatus })
                .eq("id", task.id);

            if (error) throw error;
            fetchData();
            // Optional: Success toast? For status change, maybe too noisy.
        } catch (error) {
            console.error("Error updating status:", error);
            showAlert("Error", "Failed to update status.", "error");
        }
    };

    const filteredTasks = tasks.filter(task => {
        if (filterStatus === "all") return true;
        return task.status === filterStatus;
    });

    const getAssigneeLabel = (task) => {
        if (task.assigned_team) {
            return task.assigned_team.name;
        }
        if (task.assigned_user) {
            return task.assigned_user.full_name || task.assigned_user.email;
        }
        return "Unassigned";
    };

    const formatDeadline = (deadline) => {
        if (!deadline) return "No deadline";
        const date = new Date(deadline);
        const now = new Date();
        const isOverdue = date < now;

        return (
            <span className={isOverdue ? "text-red-400" : "text-white/50"}>
                {date.toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}
            </span>
        );
    };

    const canManageTask = (task) => {
        return isPresident() || task.created_by === profile?.id;
    };

    return (
        <div className="flex min-h-screen">
            <NetworkSidebar />

            <main className="flex-1 p-6 lg:p-10 pt-24 lg:pt-10 overflow-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8"
                >
                    <div>
                        <h1 className="text-3xl lg:text-4xl font-serif font-bold text-white mb-2">
                            Tasks
                        </h1>
                        <p className="text-white/50">
                            {isPresident() ? "Manage all tasks" : "View your assigned tasks"}
                        </p>
                    </div>

                    <div className="flex gap-2">
                        <button
                            onClick={fetchData}
                            className={`p-3 bg-white/5 text-white/50 hover:text-white rounded-xl hover:bg-white/10 transition-colors ${loading ? "animate-spin" : ""}`}
                            title="Refresh Tasks"
                        >
                            <RefreshCw className="w-5 h-5" />
                        </button>
                        {(isPresident() || profile?.role === "head" || isHeadOfAny) && (
                            <button
                                onClick={() => {
                                    setEditingTask(null);
                                    setShowModal(true);
                                }}
                                className="flex items-center gap-2 px-5 py-3 bg-teal text-black font-bold rounded-xl hover:bg-teal/80 transition-colors"
                            >
                                <Plus className="w-5 h-5" />
                                Create Task
                            </button>
                        )}
                    </div>
                </motion.div>

                {/* Filters */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="flex gap-2 mb-6 overflow-x-auto pb-2"
                >
                    <button
                        onClick={() => setFilterStatus("all")}
                        className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors whitespace-nowrap ${filterStatus === "all"
                            ? "bg-white/10 text-white"
                            : "text-white/50 hover:text-white"
                            }`}
                    >
                        All ({tasks.length})
                    </button>
                    {Object.entries(STATUS_CONFIG).map(([key, config]) => {
                        const count = tasks.filter(t => t.status === key).length;
                        return (
                            <button
                                key={key}
                                onClick={() => setFilterStatus(key)}
                                className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors whitespace-nowrap ${filterStatus === key
                                    ? config.color
                                    : "text-white/50 hover:text-white"
                                    }`}
                            >
                                {config.label} ({count})
                            </button>
                        );
                    })}
                </motion.div>

                {/* Tasks List */}
                {loading ? (
                    <div className="flex items-center justify-center py-20">
                        <Loader2 className="w-10 h-10 text-teal animate-spin" />
                    </div>
                ) : filteredTasks.length === 0 ? (
                    <div className="text-center py-20">
                        <ListTodo className="w-16 h-16 text-white/10 mx-auto mb-4" />
                        <h3 className="text-xl text-white/50 mb-2">No Tasks Found</h3>
                        <p className="text-white/30">
                            {filterStatus !== "all" ? "Try changing the filter" : "Create your first task"}
                        </p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        {filteredTasks.map((task, index) => {
                            const StatusIcon = STATUS_CONFIG[task.status]?.icon || Clock;
                            const statusConfig = STATUS_CONFIG[task.status] || STATUS_CONFIG.pending;
                            // Define permissions in local scope
                            const canApproveTask = profile?.role === "head" || isPresident() || isHeadOfAny;

                            return (
                                <motion.div
                                    key={task.id}
                                    initial={{ opacity: 0, y: 20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: index * 0.03 }}
                                    className="bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-2xl p-5 hover:border-teal/20 transition-colors"
                                >
                                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                                        <div className="flex-1">
                                            <div className="flex items-center gap-3 mb-2">
                                                <h3 className="text-lg font-medium text-white">{task.title}</h3>
                                                <span className={`inline-flex items-center gap-1 px-2 py-0.5 text-[10px] uppercase tracking-widest rounded-full border ${statusConfig.color}`}>
                                                    <StatusIcon className="w-3 h-3" />
                                                    {statusConfig.label}
                                                </span>
                                            </div>

                                            {task.description && (
                                                <p className="text-white/50 text-sm mb-3 line-clamp-2">{task.description}</p>
                                            )}

                                            <div className="flex flex-wrap items-center gap-4 text-sm">
                                                <div className="flex items-center gap-2 text-white/40">
                                                    {task.assigned_team ? (
                                                        <Users className="w-4 h-4" />
                                                    ) : (
                                                        <User className="w-4 h-4" />
                                                    )}
                                                    <span>{getAssigneeLabel(task)}</span>
                                                </div>

                                                <div className="flex items-center gap-2">
                                                    <Calendar className="w-4 h-4 text-white/40" />
                                                    {formatDeadline(task.deadline)}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-2">
                                            {/* Approval Actions for Head */}
                                            {canApproveTask && task.assigned_team && (task.status === "approval_start" || task.status === "approval_completion") && (
                                                <div className="flex items-center gap-2">
                                                    <button
                                                        onClick={() => handleStatusChange(task, task.status === "approval_start" ? "in_progress" : "completed")}
                                                        className="px-3 py-1.5 bg-green-500/20 text-green-400 text-xs font-bold rounded-lg hover:bg-green-500/30"
                                                    >
                                                        Approve
                                                    </button>
                                                    <button
                                                        onClick={() => handleStatusChange(task, task.status === "approval_start" ? "pending" : "in_progress")}
                                                        className="px-3 py-1.5 bg-red-500/20 text-red-400 text-xs font-bold rounded-lg hover:bg-red-500/30"
                                                    >
                                                        Reject
                                                    </button>
                                                </div>
                                            )}

                                            {/* Action Buttons for Members (Request Logic) */}
                                            {!canApproveTask && task.assigned_team && (
                                                <>
                                                    {task.status === "pending" && (
                                                        <button
                                                            onClick={() => handleStatusChange(task, "in_progress")}
                                                            className="px-3 py-1.5 bg-teal/20 text-teal text-xs font-bold rounded-lg hover:bg-teal/30"
                                                        >
                                                            Request Start
                                                        </button>
                                                    )}
                                                    {task.status === "in_progress" && (
                                                        <button
                                                            onClick={() => handleStatusChange(task, "completed")}
                                                            className="px-3 py-1.5 bg-green-500/20 text-green-400 text-xs font-bold rounded-lg hover:bg-green-500/30"
                                                        >
                                                            Request Finish
                                                        </button>
                                                    )}
                                                </>
                                            )}

                                            {/* Standard Dropdown (Only for Individual Tasks OR if Head wants manual override) */}
                                            {(!task.assigned_team || canApproveTask) && !["approval_start", "approval_completion"].includes(task.status) && (
                                                <select
                                                    value={task.status}
                                                    onChange={(e) => handleStatusChange(task, e.target.value)}
                                                    className="appearance-none bg-gray-800 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:border-teal/50 outline-none"
                                                    style={{ colorScheme: 'dark' }}
                                                >
                                                    {Object.entries(STATUS_CONFIG).map(([key, config]) => {
                                                        // Filter out approval states from dropdown to avoid confusion
                                                        if (key.includes("approval")) return null;
                                                        return <option key={key} value={key} className="bg-gray-800 text-white">{config.label}</option>;
                                                    })}
                                                </select>
                                            )}

                                            {canManageTask(task) && (
                                                <>
                                                    <button
                                                        onClick={() => {
                                                            setEditingTask(task);
                                                            setShowModal(true);
                                                        }}
                                                        className="p-2 text-white/40 hover:text-teal hover:bg-teal/10 rounded-lg transition-colors"
                                                    >
                                                        <Edit3 className="w-4 h-4" />
                                                    </button>
                                                    <button
                                                        onClick={() => handleDeleteTask(task.id)}
                                                        className="p-2 text-white/40 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                </motion.div>
                            );
                        })}
                    </div>
                )}
            </main>

            {/* Create/Edit Task Modal */}
            <AnimatePresence>
                {showModal && (
                    <CreateTaskModal
                        task={editingTask}
                        teams={teams}
                        members={members}
                        onClose={() => {
                            setShowModal(false);
                            setEditingTask(null);
                        }}
                        onSuccess={() => {
                            setShowModal(false);
                            setEditingTask(null);
                            fetchData();
                        }}
                    />
                )}
            </AnimatePresence>
            {/* Global Status/Confirmation Modal */}
            <ConfirmationModal
                isOpen={statusModal.isOpen}
                type={statusModal.type}
                title={statusModal.title}
                message={statusModal.message}
                isDangerous={statusModal.isDangerous}
                onClose={() => setStatusModal(prev => ({ ...prev, isOpen: false }))}
                onConfirm={statusModal.onConfirm ? () => {
                    statusModal.onConfirm();
                    setStatusModal(prev => ({ ...prev, isOpen: false }));
                } : null}
            />
        </div>
    );
}

function CreateTaskModal({ task, teams, members, onClose, onSuccess }) {
    const { profile, isPresident } = useAuth();
    const [title, setTitle] = useState(task?.title || "");
    const [description, setDescription] = useState(task?.description || "");
    const [assignType, setAssignType] = useState(task?.assigned_to_team ? "team" : "user");
    const [assignToTeam, setAssignToTeam] = useState(task?.assigned_to_team || "");
    const [assignToUser, setAssignToUser] = useState(task?.assigned_to_user || "");
    const [deadline, setDeadline] = useState(task?.deadline ? new Date(task.deadline).toISOString().slice(0, 16) : "");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const supabase = createClient();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");

        if (!title.trim()) {
            setError("Task title is required");
            return;
        }

        if (assignType === "team" && !assignToTeam) {
            setError("Please select a team");
            return;
        }

        if (assignType === "user" && !assignToUser) {
            setError("Please select a user");
            return;
        }

        setSaving(true);

        try {
            const taskData = {
                title: title.trim(),
                description: description.trim() || null,
                assigned_to_team: assignType === "team" ? assignToTeam : null,
                assigned_to_user: assignType === "user" ? assignToUser : null,
                deadline: deadline ? new Date(deadline).toISOString() : null
            };

            if (task) {
                // Update existing task
                const { error: updateError } = await supabase
                    .from("tasks")
                    .update(taskData)
                    .eq("id", task.id);

                if (updateError) throw updateError;
            } else {
                // Create new task
                const { error: insertError } = await supabase
                    .from("tasks")
                    .insert({
                        ...taskData,
                        created_by: profile.id,
                        status: "pending"
                    });

                if (insertError) throw insertError;
            }

            onSuccess();
        } catch (err) {
            console.error("Error saving task:", err);
            setError(err.message || "Failed to save task");
        } finally {
            setSaving(false);
        }
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        >
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-gray-900/95 backdrop-blur-xl border border-white/10 rounded-2xl w-full max-w-lg overflow-hidden max-h-[90vh] overflow-y-auto"
            >
                {/* Modal Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-white/5 sticky top-0 bg-gray-900/95 backdrop-blur-xl">
                    <h2 className="text-xl font-serif font-bold text-white">
                        {task ? "Edit Task" : "Create New Task"}
                    </h2>
                    <button onClick={onClose} className="text-white/50 hover:text-white">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Modal Body */}
                <form onSubmit={handleSubmit} className="p-6 space-y-5">
                    {error && (
                        <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400 text-sm flex items-center gap-2">
                            <AlertCircle className="w-4 h-4 flex-shrink-0" />
                            {error}
                        </div>
                    )}

                    {/* Title */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Task Title *
                        </label>
                        <input
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            placeholder="Enter task title"
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                        />
                    </div>

                    {/* Description */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Description
                        </label>
                        <textarea
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Task details..."
                            rows={3}
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none resize-none"
                        />
                    </div>

                    {/* Assign Type */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Assign To *
                        </label>
                        <div className="grid grid-cols-2 gap-3">
                            <button
                                type="button"
                                onClick={() => setAssignType("team")}
                                className={`flex items-center justify-center gap-2 px-4 py-3 rounded-xl border transition-all ${assignType === "team"
                                    ? "bg-teal/10 border-teal/50 text-teal"
                                    : "bg-white/5 border-white/10 text-white/50 hover:border-white/30"
                                    }`}
                            >
                                <Users className="w-5 h-5" />
                                Team
                            </button>
                            <button
                                type="button"
                                onClick={() => setAssignType("user")}
                                className={`flex items-center justify-center gap-2 px-4 py-3 rounded-xl border transition-all ${assignType === "user"
                                    ? "bg-purple-500/10 border-purple-500/50 text-purple-400"
                                    : "bg-white/5 border-white/10 text-white/50 hover:border-white/30"
                                    }`}
                            >
                                <User className="w-5 h-5" />
                                Individual
                            </button>
                        </div>
                    </div>

                    {/* Team/User Selection with Privileges */}
                    {assignType === "team" ? (
                        <div className="space-y-2">
                            <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                                Select Team *
                            </label>
                            <select
                                value={assignToTeam}
                                onChange={(e) => setAssignToTeam(e.target.value)}
                                className="w-full appearance-none bg-gray-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none"
                                style={{ colorScheme: 'dark' }}
                            >
                                <option value="" className="bg-gray-800 text-white/50">Choose a team...</option>
                                {teams.map(team => (
                                    <option key={team.id} value={team.id} className="bg-gray-800 text-white">
                                        {team.name} ({team.type === "fest" ? "Fest" : "General"})
                                    </option>
                                ))}
                            </select>
                        </div>
                    ) : (
                        <div className="space-y-2">
                            <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                                Select Member *
                            </label>
                            <select
                                value={assignToUser}
                                onChange={(e) => setAssignToUser(e.target.value)}
                                className="w-full appearance-none bg-gray-800 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none"
                                style={{ colorScheme: 'dark' }}
                            >
                                <option value="" className="bg-gray-800 text-white/50">Choose a member...</option>
                                {members
                                    .filter(m => {
                                        // Filter logic:
                                        // 1. President/Core: See everyone
                                        if (isPresident()) return true;
                                        // 2. Head: See their team members (Need team context? We fetched ALL members, but we don't have their team mapping here easily unless we fetch it.
                                        // Actually `members` fetch in fetchData didn't filter.
                                        // But wait, the user wants: "Head should have privilege of assigning...".

                                        // Quick Fix depending on available data:
                                        // If Head: Allow all for now (as checking team membership requires more data), OR assume Heads know who to pick.
                                        // If Member: Only show THEMSELVES.
                                        if (profile.role === "member") {
                                            return m.id === profile.id;
                                        }
                                        return true; // Heads see all (simplification, to avoid complex filters without team-member mapping)
                                    })
                                    .map(member => (
                                        <option key={member.id} value={member.id} className="bg-gray-800 text-white">
                                            {member.full_name || member.email}
                                        </option>
                                    ))}
                            </select>
                            {profile.role === "member" && (
                                <p className="text-[10px] text-white/30">Members can only assign tasks to themselves.</p>
                            )}
                        </div>
                    )}

                    {/* Deadline */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Deadline
                        </label>
                        <input
                            type="datetime-local"
                            value={deadline}
                            onChange={(e) => setDeadline(e.target.value)}
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-teal/50 outline-none"
                        />
                    </div>

                    {/* Submit */}
                    <button
                        type="submit"
                        disabled={saving}
                        className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors disabled:opacity-50"
                    >
                        {saving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Saving...
                            </>
                        ) : (
                            task ? "Update Task" : "Create Task"
                        )}
                    </button>
                </form>
            </motion.div>
        </motion.div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useAuth } from "@/context/AuthContext";
import NetworkSidebar from "@/components/network/Sidebar";
import { createClient } from "@/lib/supabase/client";
import {
    Users,
    Plus,
    Layers,
    PartyPopper,
    UserPlus,
    Trash2,
    Edit3,
    Loader2,
    X,
    Shield
} from "lucide-react";
import ConfirmationModal from "@/components/ui/ConfirmationModal";

export default function TeamsPage() {
    const { profile, canManageTeams } = useAuth();
    const [teams, setTeams] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [showMembersModal, setShowMembersModal] = useState(false);
    const [selectedTeamForMembers, setSelectedTeamForMembers] = useState(null);
    const [editingTeam, setEditingTeam] = useState(null);

    // Global Alert/Confirm State
    const [statusModal, setStatusModal] = useState({
        isOpen: false,
        type: "confirm",
        title: "",
        message: "",
        onConfirm: null
    });

    const showAlert = (title, message, type = "success") => {
        setStatusModal({ isOpen: true, title, message, type, onConfirm: null });
    };

    const showConfirm = (title, message, onConfirm, isDangerous = false) => {
        setStatusModal({ isOpen: true, title, message, type: "confirm", onConfirm, isDangerous });
    };
    const supabase = createClient();

    // Fetch teams
    const fetchTeams = useCallback(async () => {
        if (!profile?.id) return;
        try {
            const { data, error } = await supabase
                .from("teams")
                .select(`
                    *,
                    team_members (
                        id,
                        role,
                        user_id,
                        profiles:user_id (
                            id,
                            full_name,
                            email,
                            role
                        )
                    )
                `)
                .order("created_at", { ascending: false });

            if (error) throw error;
            setTeams(data || []);
        } catch (error) {
            console.error("Error fetching teams:", error);
        } finally {
            setLoading(false);
        }
    }, [profile?.id, supabase]);

    useEffect(() => {
        fetchTeams();

        // Realtime subscription
        const channel = supabase
            .channel("teams-changes")
            .on("postgres_changes", { event: "*", schema: "public", table: "teams" }, () => {
                fetchTeams();
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [fetchTeams, supabase]);

    const handleDeleteTeam = async (teamId, teamName) => {
        showConfirm(
            "Delete Team",
            `Are you sure you want to delete "${teamName}"? This action cannot be undone.`,
            async () => {
                try {
                    const { error } = await supabase.from("teams").delete().eq("id", teamId);
                    if (error) throw error;
                    fetchTeams();
                    showAlert("Deleted", "Team has been removed successfully.", "success");
                } catch (error) {
                    console.error("Error deleting team:", error);
                    showAlert("Error", "Failed to delete team.", "error");
                }
            },
            true
        );
    };

    const getTeamHead = (team) => {
        const headMember = team.team_members?.find(m => m.role === "head");
        return headMember?.profiles?.full_name || headMember?.profiles?.email || "No Head Assigned";
    };

    const getMemberCount = (team) => {
        return team.team_members?.length || 0;
    };

    return (
        <div className="flex min-h-screen">
            <NetworkSidebar />

            <main className="flex-1 p-6 lg:p-10 pt-24 lg:pt-10 overflow-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10"
                >
                    <div>
                        <h1 className="text-3xl lg:text-4xl font-serif font-bold text-white mb-2">
                            Teams
                        </h1>
                        <p className="text-white/50">
                            Manage General and Fest teams
                        </p>
                    </div>

                    {canManageTeams() && (
                        <button
                            onClick={() => {
                                setEditingTeam(null);
                                setShowModal(true);
                            }}
                            className="flex items-center gap-2 px-5 py-3 bg-teal text-black font-bold rounded-xl hover:bg-teal/80 transition-colors"
                        >
                            <Plus className="w-5 h-5" />
                            Create Team
                        </button>
                    )}
                </motion.div>

                {loading ? (
                    <div className="flex items-center justify-center py-20">
                        <Loader2 className="w-10 h-10 text-teal animate-spin" />
                    </div>
                ) : teams.length === 0 ? (
                    <div className="text-center py-20">
                        <Users className="w-16 h-16 text-white/10 mx-auto mb-4" />
                        <h3 className="text-xl text-white/50 mb-2">No Teams Yet</h3>
                        {canManageTeams() && (
                            <button
                                onClick={() => setShowModal(true)}
                                className="text-teal hover:underline"
                            >
                                Create your first team
                            </button>
                        )}
                    </div>
                ) : (
                    <div className="space-y-12">
                        {/* Fest Teams Section */}
                        <section>
                            <div className="flex items-center gap-3 mb-6">
                                <PartyPopper className="w-6 h-6 text-purple-400" />
                                <h2 className="text-2xl font-serif font-bold text-white">Fest Teams</h2>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {teams.filter(t => t.type === 'fest').length > 0 ? (
                                    teams.filter(t => t.type === 'fest').map((team, index) => (
                                        <TeamCard
                                            key={team.id}
                                            team={team}
                                            index={index}
                                            canManageTeams={canManageTeams}
                                            onEdit={() => {
                                                setEditingTeam(team);
                                                setShowModal(true);
                                            }}
                                            onDelete={() => handleDeleteTeam(team.id, team.name)}
                                            onManageMembers={() => {
                                                setSelectedTeamForMembers(team);
                                                setShowMembersModal(true);
                                            }}
                                        />
                                    ))
                                ) : (
                                    <p className="text-white/30 text-sm">No fest teams created yet.</p>
                                )}
                            </div>
                        </section>

                        {/* General Teams Section */}
                        <section>
                            <div className="flex items-center gap-3 mb-6">
                                <Layers className="w-6 h-6 text-teal" />
                                <h2 className="text-2xl font-serif font-bold text-white">General Teams</h2>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {teams.filter(t => t.type !== 'fest').length > 0 ? (
                                    teams.filter(t => t.type !== 'fest').map((team, index) => (
                                        <TeamCard
                                            key={team.id}
                                            team={team}
                                            index={index}
                                            canManageTeams={canManageTeams}
                                            onEdit={() => {
                                                setEditingTeam(team);
                                                setShowModal(true);
                                            }}
                                            onDelete={() => handleDeleteTeam(team.id, team.name)}
                                            onManageMembers={() => {
                                                setSelectedTeamForMembers(team);
                                                setShowMembersModal(true);
                                            }}
                                        />
                                    ))
                                ) : (
                                    <p className="text-white/30 text-sm">No general teams created yet.</p>
                                )}
                            </div>
                        </section>
                    </div>
                )}
            </main>

            {/* Create/Edit Team Modal */}
            <AnimatePresence>
                {showModal && (
                    <CreateTeamModal
                        team={editingTeam}
                        onClose={() => {
                            setShowModal(false);
                            setEditingTeam(null);
                        }}
                        onSuccess={() => {
                            setShowModal(false);
                            setEditingTeam(null);
                            fetchTeams();
                        }}
                    />
                )}
            </AnimatePresence>

            {/* Manage Members Modal */}
            <AnimatePresence>
                {showMembersModal && selectedTeamForMembers && (
                    <ManageTeamMembersModal
                        team={selectedTeamForMembers}
                        onClose={() => {
                            setShowMembersModal(false);
                            setSelectedTeamForMembers(null);
                        }}
                        onSuccess={() => {
                            fetchTeams();
                        }}
                        // Pass global alerts to child
                        showAlert={showAlert}
                        showConfirm={showConfirm}
                    />
                )}
            </AnimatePresence>

            {/* Global Status/Confirmation Modal */}
            <ConfirmationModal
                isOpen={statusModal.isOpen}
                type={statusModal.type}
                title={statusModal.title}
                message={statusModal.message}
                isDangerous={statusModal.isDangerous}
                onClose={() => setStatusModal(prev => ({ ...prev, isOpen: false }))}
                onConfirm={statusModal.onConfirm ? () => {
                    statusModal.onConfirm();
                    setStatusModal(prev => ({ ...prev, isOpen: false }));
                } : null}
            />
        </div>
    );
}

function CreateTeamModal({ team, onClose, onSuccess }) {
    const { profile } = useAuth();
    const [name, setName] = useState(team?.name || "");
    const [type, setType] = useState(team?.type || "general");
    const [description, setDescription] = useState(team?.description || "");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const supabase = createClient();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");

        if (!name.trim()) {
            setError("Team name is required");
            return;
        }

        setSaving(true);

        try {
            if (team) {
                // Update existing team
                const { error: updateError } = await supabase
                    .from("teams")
                    .update({ name: name.trim(), type, description: description.trim() })
                    .eq("id", team.id);

                if (updateError) throw updateError;
            } else {
                // Create new team
                const { error: insertError } = await supabase
                    .from("teams")
                    .insert({
                        name: name.trim(),
                        type,
                        description: description.trim(),
                        created_by: profile.id
                    });

                if (insertError) throw insertError;
            }

            onSuccess();
        } catch (err) {
            console.error("Error saving team:", err);
            setError(err.message || "Failed to save team");
        } finally {
            setSaving(false);
        }
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        >
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-gray-900/95 backdrop-blur-xl border border-white/10 rounded-2xl w-full max-w-md overflow-hidden"
            >
                {/* Modal Header */}
                <div className="flex items-center justify-between px-6 py-4 border-b border-white/5">
                    <h2 className="text-xl font-serif font-bold text-white">
                        {team ? "Edit Team" : "Create New Team"}
                    </h2>
                    <button onClick={onClose} className="text-white/50 hover:text-white">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Modal Body */}
                <form onSubmit={handleSubmit} className="p-6 space-y-5">
                    {error && (
                        <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400 text-sm">
                            {error}
                        </div>
                    )}

                    {/* Team Name */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Team Name
                        </label>
                        <input
                            type="text"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            placeholder="e.g., Content Team"
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none transition-all"
                        />
                    </div>

                    {/* Team Type */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Team Type
                        </label>
                        <div className="grid grid-cols-2 gap-3">
                            <button
                                type="button"
                                onClick={() => setType("general")}
                                className={`flex items-center justify-center gap-2 px-4 py-3 rounded-xl border transition-all ${type === "general"
                                    ? "bg-teal/10 border-teal/50 text-teal"
                                    : "bg-white/5 border-white/10 text-white/50 hover:border-white/30"
                                    }`}
                            >
                                <Layers className="w-5 h-5" />
                                General
                            </button>
                            <button
                                type="button"
                                onClick={() => setType("fest")}
                                className={`flex items-center justify-center gap-2 px-4 py-3 rounded-xl border transition-all ${type === "fest"
                                    ? "bg-purple-500/10 border-purple-500/50 text-purple-400"
                                    : "bg-white/5 border-white/10 text-white/50 hover:border-white/30"
                                    }`}
                            >
                                <PartyPopper className="w-5 h-5" />
                                Fest
                            </button>
                        </div>
                    </div>

                    {/* Description */}
                    <div className="space-y-2">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Description (Optional)
                        </label>
                        <textarea
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Brief description of the team's purpose"
                            rows={3}
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none transition-all resize-none"
                        />
                    </div>

                    {/* Submit */}
                    <button
                        type="submit"
                        disabled={saving}
                        className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors disabled:opacity-50"
                    >
                        {saving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Saving...
                            </>
                        ) : (
                            <>
                                {team ? "Update Team" : "Create Team"}
                            </>
                        )}
                    </button>
                </form>
            </motion.div>
        </motion.div>
    );
}

function TeamCard({ team, index, canManageTeams, onEdit, onDelete, onManageMembers }) {
    const getTeamHead = (t) => {
        const headMember = t.team_members?.find(m => m.role === "head");
        return headMember?.profiles?.full_name || headMember?.profiles?.email || "No Head Assigned";
    };

    const getMemberCount = (t) => {
        return t.team_members?.length || 0;
    };

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.05 }}
            className="group bg-gray-900/40 backdrop-blur-xl border border-white/5 rounded-2xl overflow-hidden hover:border-teal/30 transition-colors flex flex-col h-full"
        >
            {/* Team Header */}
            <div className={`p-5 border-b border-white/5 ${team.type === "fest" ? "bg-gradient-to-r from-purple-500/10 to-pink-500/10" : "bg-gradient-to-r from-teal/5 to-lime/5"}`}>
                <div className="flex items-start justify-between">
                    <div className="flex items-center gap-3">
                        {team.type === "fest" ? (
                            <PartyPopper className="w-6 h-6 text-purple-400" />
                        ) : (
                            <Layers className="w-6 h-6 text-teal" />
                        )}
                        <div>
                            <h3 className="text-lg font-serif font-bold text-white line-clamp-1">{team.name}</h3>
                            <span className={`inline-block mt-1 px-2 py-0.5 text-[10px] uppercase tracking-widest rounded-full ${team.type === "fest"
                                ? "bg-purple-500/20 text-purple-400 border border-purple-500/30"
                                : "bg-teal/20 text-teal border border-teal/30"
                                }`}>
                                {team.type === "fest" ? "Fest Team" : "General Team"}
                            </span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Team Body */}
            <div className="p-5 flex-1">
                <p className="text-white/40 text-sm mb-4 line-clamp-2 min-h-[40px]">
                    {team.description || "No description"}
                </p>

                <div className="flex items-center justify-between text-sm">
                    <div className="flex items-center gap-2 text-white/50">
                        <Shield className="w-4 h-4 text-purple-400" />
                        <span className="truncate max-w-[120px]" title={getTeamHead(team)}>{getTeamHead(team)}</span>
                    </div>
                    <div className="flex items-center gap-2 text-white/50">
                        <Users className="w-4 h-4 text-teal" />
                        <span>{getMemberCount(team)} members</span>
                    </div>
                </div>
            </div>

            {/* Team Actions */}
            {canManageTeams() && (
                <div className="px-5 pb-5 pt-0 flex flex-col gap-2">
                    {team.type === "fest" && (
                        <button
                            onClick={onManageMembers}
                            className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white/70 hover:bg-white/10 hover:text-white transition-colors text-sm"
                        >
                            <UserPlus className="w-4 h-4" />
                            Manage Members
                        </button>
                    )}
                    <div className="flex gap-2">
                        <button
                            onClick={onEdit}
                            className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white/70 hover:bg-white/10 hover:text-white transition-colors text-sm"
                        >
                            <Edit3 className="w-4 h-4" />
                            Edit
                        </button>
                        <button
                            onClick={onDelete}
                            className="flex items-center justify-center gap-2 px-4 py-2 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400/70 hover:bg-red-500/20 hover:text-red-400 transition-colors text-sm"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                </div>
            )}
        </motion.div>
    );
}

function ManageTeamMembersModal({ team, onClose, onSuccess, showAlert, showConfirm }) {
    const { profile } = useAuth();
    const [searchQuery, setSearchQuery] = useState("");
    const [searchResults, setSearchResults] = useState([]);
    const [selectedUser, setSelectedUser] = useState(null);
    const [selectedRole, setSelectedRole] = useState("member");
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const supabase = createClient();

    useEffect(() => {
        const timer = setTimeout(() => {
            if (searchQuery.trim().length >= 2) {
                searchUsers();
            } else {
                setSearchResults([]);
            }
        }, 300);
        return () => clearTimeout(timer);
    }, [searchQuery]);

    const searchUsers = async () => {
        setLoading(true);
        try {
            const existingMemberIds = team.team_members?.map(m => m.user_id) || [];

            let query = supabase
                .from("profiles")
                .select("id, full_name, email, role")
                .or(`full_name.ilike.%${searchQuery}%,email.ilike.%${searchQuery}%`)
                .limit(10);

            const { data, error } = await query;
            if (error) throw error;

            const availableUsers = data?.filter(u => !existingMemberIds.includes(u.id)) || [];
            setSearchResults(availableUsers);
        } catch (err) {
            console.error("Search error:", err);
        } finally {
            setLoading(false);
        }
    };

    const handleAddMember = async () => {
        if (!selectedUser) return;
        setSaving(true);
        setError("");

        try {
            const { error: insertError } = await supabase
                .from("team_members")
                .insert({
                    team_id: team.id,
                    user_id: selectedUser.id,
                    role: selectedRole
                });

            if (insertError) throw insertError;

            setSearchQuery("");
            setSearchResults([]);
            onSuccess();
            showAlert("Member Added", `Added ${selectedUser.full_name || selectedUser.email} as ${selectedRole}`, "success");

        } catch (err) {
            console.error("Error adding member:", err);
            showAlert("Error", err.message || "Failed to add member", "error");
        } finally {
            setSaving(false);
        }
    };

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        >
            <motion.div
                initial={{ opacity: 0, scale: 0.95, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 20 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-gray-900/95 backdrop-blur-xl border border-white/10 rounded-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[80vh]"
            >
                <div className="flex items-center justify-between px-6 py-4 border-b border-white/5">
                    <div>
                        <h2 className="text-xl font-serif font-bold text-white">Manage Members</h2>
                        <p className="text-white/40 text-xs mt-0.5">{team.name}</p>
                    </div>
                    <button onClick={onClose} className="text-white/50 hover:text-white">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <div className="p-6 space-y-6 overflow-y-auto">
                    <div className="space-y-4">
                        <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">
                            Add New Member
                        </label>

                        <div className="relative">
                            <input
                                type="text"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                placeholder="Search by name or email..."
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-white/20 focus:border-teal/50 outline-none"
                            />
                            {loading && (
                                <div className="absolute right-4 top-3.5">
                                    <Loader2 className="w-5 h-5 text-teal animate-spin" />
                                </div>
                            )}
                        </div>

                        {searchResults.length > 0 && (
                            <div className="bg-black/20 border border-white/5 rounded-xl overflow-hidden max-h-40 overflow-y-auto">
                                {searchResults.map(user => (
                                    <button
                                        key={user.id}
                                        onClick={() => setSelectedUser(user)}
                                        className={`w-full flex items-center justify-between p-3 text-left transition-colors ${selectedUser?.id === user.id ? 'bg-teal/20' : 'hover:bg-white/5'}`}
                                    >
                                        <div>
                                            <p className="text-white text-sm font-medium">{user.full_name || "Unnamed User"}</p>
                                            <p className="text-white/40 text-xs">{user.email}</p>
                                        </div>
                                        {selectedUser?.id === user.id && <div className="w-2 h-2 bg-teal rounded-full" />}
                                    </button>
                                ))}
                            </div>
                        )}

                        {selectedUser && (
                            <div className="p-4 bg-teal/5 border border-teal/20 rounded-xl space-y-4 animate-in fade-in slide-in-from-top-2">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <p className="text-teal font-bold text-sm">Selected User</p>
                                        <p className="text-white text-sm">{selectedUser.full_name}</p>
                                    </div>
                                    <button onClick={() => setSelectedUser(null)} className="text-white/30 hover:text-white">
                                        <X className="w-4 h-4" />
                                    </button>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] uppercase tracking-widest text-white/40 font-mono">Assign Role</label>
                                    <div className="flex gap-2">
                                        <button
                                            onClick={() => setSelectedRole("member")}
                                            className={`flex-1 py-2 rounded-lg text-sm border font-medium ${selectedRole === "member"
                                                ? "bg-teal text-black border-teal"
                                                : "bg-transparent border-white/10 text-white/50 hover:text-white"}`}
                                        >
                                            Member
                                        </button>
                                        <button
                                            onClick={() => setSelectedRole("head")}
                                            className={`flex-1 py-2 rounded-lg text-sm border font-medium ${selectedRole === "head"
                                                ? "bg-purple-500 text-white border-purple-500"
                                                : "bg-transparent border-white/10 text-white/50 hover:text-white"}`}
                                        >
                                            Head
                                        </button>
                                    </div>
                                </div>

                                <button
                                    onClick={handleAddMember}
                                    disabled={saving}
                                    className="w-full bg-teal text-black font-bold py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-teal/80 transition-colors disabled:opacity-50"
                                >
                                    {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <UserPlus className="w-4 h-4" />}
                                    Confirm Addition
                                </button>
                                {error && <p className="text-red-400 text-xs text-center">{error}</p>}
                            </div>
                        )}
                    </div>

                    <div className="pt-4 border-t border-white/5">
                        <h3 className="text-white/50 text-xs uppercase tracking-widest mb-3">Current Members ({team.team_members?.length || 0})</h3>
                        <div className="space-y-2">
                            {team.team_members?.map(member => (
                                <div key={member.id} className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/5">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${member.role === 'head' ? 'bg-purple-500 text-white' : 'bg-gray-700 text-white/70'}`}>
                                            {member.profiles?.full_name?.[0] || "?"}
                                        </div>
                                        <div>
                                            <p className="text-white text-sm font-medium">{member.profiles?.full_name || member.profiles?.email}</p>
                                            <p className="text-white/30 text-[10px] uppercase">{member.role}</p>
                                        </div>
                                    </div>
                                    <button
                                        onClick={() => {
                                            showConfirm(
                                                "Remove Member",
                                                `Are you sure you want to remove ${member.profiles?.full_name || 'this member'} from the team?`,
                                                async () => {
                                                    const { error } = await supabase.from('team_members').delete().eq('id', member.id);
                                                    if (error) showAlert("Error", "Failed to remove member", "error");
                                                    else {
                                                        onSuccess();
                                                        showAlert("Removed", "Member has been removed from the team.", "success");
                                                    }
                                                },
                                                true
                                            );
                                        }}
                                        className="p-2 text-white/20 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </motion.div>
        </motion.div>
    );
}

