                            lim<sub className="text-[0.6em] not-italic">xÔåÆÔê×</sub> (1 + 1/x)<sup className="text-xs">x</sup> = e
                        </span>
                    </div>
                </div>
            </div>

            {/* Corner Crosshairs with Pulse */}
            <div className="absolute top-0 left-0 w-12 h-12 pointer-events-none opacity-20">
