        >
            <div
                className="absolute inset-0 opacity-20 pointer-events-none"
                style={{
                    background: `radial-gradient(circle 355px at ${mousePosition.x}px ${mousePosition.y}px, rgba(58,188,179,0.2) 0%, transparent 20%)`
                }}
            />
        </div>
    );
}

