"use client";

import { useEffect, useState } from "react";
import { motion, AnimatePresence, animate } from "framer-motion";

export default function Preloader() {
    const [isLoading, setIsLoading] = useState(true);
    const [count, setCount] = useState(0);

    useEffect(() => {
        // Check local storage for timestamp
        const lastShown = typeof window !== 'undefined' ? localStorage.getItem("rmc-legacy-preloader-timestamp") : null;
        const ONE_HOUR = 60 * 60 * 1000;
        const now = Date.now();

        const timeSince = lastShown ? now - (parseInt(lastShown) || 0) : Infinity;

        // Show if:
        // 1. Never shown (!lastShown)
        // 2. Expired (> ONE_HOUR)
        // 3. Just started (< 2000ms) - Fix for React Strict Mode
        const shouldShow = !lastShown || timeSince > ONE_HOUR || timeSince < 2000;

        if (!shouldShow) {
            if (isLoading) setIsLoading(false);
            return;
        }

        // Set timestamp immediately
        localStorage.setItem("rmc-legacy-preloader-timestamp", now.toString());

        // Prevent scrolling during loading
        document.body.style.overflow = "hidden";

        // Smooth Counter Animation using Framer Motion's animate
        const controls = animate(2018, 2026, {
            duration: 2,
            ease: "easeInOut",
            onUpdate: (value) => setCount(Math.floor(value)),
            onComplete: () => {
                setTimeout(() => {
                    if (isLoading) setIsLoading(false);
                    document.body.style.overflow = "";
                }, 200);
            }
        });

        return () => {
            controls.stop();
            document.body.style.overflow = "";
        };
    }, [isLoading]);

    return (
        <AnimatePresence mode="wait">
            {isLoading && (
                <motion.div
                    key="preloader"
                    initial={{ y: 0 }}
                    exit={{ y: "-100%", transition: { duration: 0.8, ease: [0.76, 0, 0.24, 1] } }}
                    className="fixed inset-0 z-[100] flex items-center justify-center bg-black text-white px-4 md:px-0"
                >
                    {/* Background Noise/Texture - Removed for now */}
                    <div className="absolute inset-0 bg-white/5 opacity-[0.05] pointer-events-none"></div>

                    <div className="relative z-10 flex flex-col items-center">
                        {/* The Counter */}
                        <div className="flex items-baseline font-serif font-bold tracking-tighter">
                            <div className="flex items-center overflow-hidden h-[1.1em] text-6xl md:text-8xl">
                                <motion.span
                                    initial={{ y: "100%" }}
                                    animate={{ y: "0%" }}
                                    transition={{ duration: 0.8, ease: "circOut" }}
                                >
                                    {count}
                                </motion.span>
                            </div>
                        </div>

                        {/* Loading Text */}
                        <motion.p
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            transition={{ delay: 0.2 }}
                            className="mt-4 font-mono text-sm uppercase tracking-[0.4em] text-teal/90 drop-shadow-[0_0_10px_rgba(58,188,179,0.5)]"
                        >
                            Loading Legacy...
                        </motion.p>
                    </div>

                    {/* Bottom Corner Tag Removed */}
                </motion.div>
            )}
        </AnimatePresence>
    );
}

"use client";

import { createContext, useContext, useEffect, useState, useMemo, useRef } from "react";
import { createClient } from "@/lib/supabase/client";

const AuthContext = createContext(undefined);

export function AuthProvider({ children }) {
    const [user, setUser] = useState(null);
    const [profile, setProfile] = useState(null);
    const [permissions, setPermissions] = useState(null);
    const [loading, setLoading] = useState(true);
    const [authReady, setAuthReady] = useState(false);

    // Create supabase client once using useMemo
    const supabase = useMemo(() => createClient(), []);

    // Track in-flight requests to prevent double fetching
    const fetchPromises = useRef(new Map());

    useEffect(() => {
        let isMounted = true;

        const initializeAuth = async () => {
            try {
                // Get the current session
                const { data: { session }, error } = await supabase.auth.getSession();

                if (error) {
                    console.error("Session error:", error);
                    if (isMounted) {
                        setLoading(false);
                        setAuthReady(true);
                    }
                    return;
                }

                // If no session, we're ready (logged out state)
                if (!session && isMounted) {
                    setLoading(false);
                    setAuthReady(true);
                }

                // If session exists, we let onAuthStateChange handle the profile fetch
            } catch (error) {
                console.warn("Auth initialization error:", error);
                if (isMounted) {
                    setLoading(false);
                    setAuthReady(true);
                }
            }
        };

        initializeAuth();

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange(
            async (event, session) => {
                console.log("Auth state changed:", event);

                if (!isMounted) return;

                if (event === 'SIGNED_OUT' || !session) {
                    setUser(null);
                    setProfile(null);
                    setPermissions(null);
                    setLoading(false);
                    setAuthReady(true);
                    return;
                }

                // If user is already set and same ID, and we have a profile, don't refetch
                if (user?.id === session.user.id && profile) {
                    setLoading(false);
                    setAuthReady(true);
                    return;
                }

                setUser(session.user);

                // UNBLOCK UI: Set ready immediately, fetch profile in background
                if (isMounted) {
                    setLoading(false);
                    setAuthReady(true);
                }

                // Fetch profile in background (don't await)
                fetchProfile(session.user.id).catch(err =>
                    console.error("Background profile fetch failed:", err)
                );
            }
        );

        return () => {
            isMounted = false;
            subscription.unsubscribe();
        };
    }, [supabase]);

    // Unified, iterative fetchProfile function
    const fetchProfile = async (userId) => {
        const fetchKey = userId;

        // Return existing promise if one is already in flight
        if (fetchPromises.current.has(fetchKey)) {
            console.log(`Using in-flight promise for user: ${userId}`);
            return fetchPromises.current.get(fetchKey);
        }

        const promise = (async () => {
            let lastError;
            // Retry loop: up to 3 attempts (0, 1, 2)
            for (let attempt = 0; attempt < 3; attempt++) {
                try {
                    console.log(`Fetching profile for user: ${userId} (Attempt ${attempt + 1})`);

                    // Race condition: 5s timeout vs Supabase request
                    const { data: profileData, error } = await Promise.race([
                        supabase
                            .from("profiles")
                            .select("*")
                            .eq("id", userId)
                            .single(),
                        new Promise((_, reject) => setTimeout(() => reject(new Error("Request timeout")), 10000))
                    ]);

                    if (error) throw error;

                    console.log("Profile fetched successfully:", profileData?.role);
                    setProfile(profileData);

                    // Set permissions based on role
                    if (profileData.role === "president") {
                        setPermissions({ can_manage_teams: true, can_manage_members: true });
                    } else if (["vice_president", "general_secretary", "joint_secretary"].includes(profileData.role)) {
                        const { data: permData } = await supabase
                            .from("delegated_permissions")
                            .select("*")
                            .eq("user_id", userId)
                            .single();
                        setPermissions(permData || { can_manage_teams: false, can_manage_members: false });
                    } else {
                        setPermissions(null);
                    }

                    return; // Success! Exit the function.

                } catch (err) {
                    // Check for specific Supabase error codes
                    // PGRST116: The result contains 0 rows (Profile not found)
                    if (err?.code === 'PGRST116') {
                        console.warn("Profile not found for user (PGRST116). Stopping retries.");
                        // Treat as success but with null profile
                        setProfile(null);
                        setPermissions(null);
                        return;
                    }

                    console.warn(`Profile fetch attempt ${attempt + 1} failed:`, err.message || err);
                    lastError = err;

                    // Wait before retrying (exponential backoff: 1s, 2s)
                    if (attempt < 2) {
                        const delay = Math.pow(2, attempt) * 1000;
                        await new Promise(resolve => setTimeout(resolve, delay));
                    }
                }
            }

            // If we exit the loop, all attempts failed
            console.error("All profile fetch attempts failed. User logged in without profile data.", lastError);
            // We do NOT set a dummy "member" profile here. 
            // We leave profile as null. The UI should handle this state (e.g. show restricted view or loading).
        })();

        // Store promise in map
        fetchPromises.current.set(fetchKey, promise);

        // Cleanup map when promise completes (success or fail)
        promise.finally(() => {
            fetchPromises.current.delete(fetchKey);
        });

        return promise;
    };

    const signIn = async (email, password) => {
        setLoading(true);
        try {
            const { data, error } = await supabase.auth.signInWithPassword({
                email: email.trim().toLowerCase(),
                password
            });

            if (error) {
                setLoading(false);
                return { data: null, error };
            }

            // Wait for profile to be fetched
            if (data?.user) {
                await fetchProfile(data.user.id);
            }

            setLoading(false);
            return { data, error: null };
        } catch (error) {
            setLoading(false);
            return { data: null, error };
        }
    };

    const signOut = async () => {
        setLoading(true);
        try {
            await supabase.auth.signOut();
            setUser(null);
            setProfile(null);
            setPermissions(null);
            // setAuthReady(true);
        } catch (error) {
            console.error("Sign out error:", error);
        } finally {
            setLoading(false);
        }
    };

    // Helper functions for permission checks
    const isPresident = () => profile?.role === "president";
    const isCoreCouncil = () => ["president", "vice_president", "general_secretary", "joint_secretary", "faculty"].includes(profile?.role);
    const isHead = () => profile?.role === "head";
    const canManageTeams = () => isPresident() || permissions?.can_manage_teams;
    const canManageMembers = () => isPresident() || permissions?.can_manage_members;

    const signUp = async (email, password, options = {}) => {
        setLoading(true);
        try {
            const { data, error } = await supabase.auth.signUp({
                email,
                password,
                options
            });
            setLoading(false);
            return { data, error };
        } catch (error) {
            setLoading(false);
            return { data: null, error };
        }
    };

    const value = {
        user,
        profile,
        permissions,
        loading,
        authReady,
        signIn,
        signUp,
        signOut,
        isPresident,
        isCoreCouncil,
        isHead,
        canManageTeams,
        canManageMembers,
        refreshProfile: () => user && fetchProfile(user.id)
    };

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error("useAuth must be used within an AuthProvider");
    }
    return context;
}

import { google } from 'googleapis';
import { Readable } from 'stream';

const SCOPES = [
    'https://www.googleapis.com/auth/drive.file',
    'https://www.googleapis.com/auth/spreadsheets',
];

/**
 * Authenticate using Service Account from Environment Variable
 */
const getAuthClient = async () => {
    // 1. Try OAuth 2.0 (User Account - Free 15GB Quota)
    if (process.env.GOOGLE_REFRESH_TOKEN && process.env.GOOGLE_CLIENT_ID) {
        const oauth2Client = new google.auth.OAuth2(
            process.env.GOOGLE_CLIENT_ID,
            process.env.GOOGLE_CLIENT_SECRET,
            process.env.GOOGLE_REDIRECT_URI || 'https://developers.google.com/oauthplayground'
        );

        oauth2Client.setCredentials({
            refresh_token: process.env.GOOGLE_REFRESH_TOKEN
        });

        return oauth2Client;
    }

    // 2. Fallback to Service Account (0GB Quota unless billed)
    if (process.env.GOOGLE_SERVICE_ACCOUNT_JSON) {
        const credentials = JSON.parse(process.env.GOOGLE_SERVICE_ACCOUNT_JSON);
        const auth = new google.auth.GoogleAuth({
            credentials,
            scopes: SCOPES,
        });
        return await auth.getClient();
    }

    throw new Error('Missing Google Credentials: Set GOOGLE_REFRESH_TOKEN (User) or GOOGLE_SERVICE_ACCOUNT_JSON (Service Account)');
};

/**
 * Upload a file to Google Drive
 */
export const uploadToDrive = async (
    fileBuffer: Buffer,
    mimeType: string,
    fileName: string,
    parentFolderId: string
) => {
    const authClient = await getAuthClient();
    const drive = google.drive({ version: 'v3', auth: authClient as any });

    const bufferStream = new Readable();
    bufferStream.push(fileBuffer);
    bufferStream.push(null);

    const fileMetadata = {
        name: fileName,
        parents: [parentFolderId],
    };

    const media = {
        mimeType: mimeType,
        body: bufferStream,
    };

    const response = await drive.files.create({
        requestBody: fileMetadata,
        media: media,
        fields: 'id, webViewLink, webContentLink',
    });

    return response.data;
};

/**
 * Get or Create a folder by name inside a parent folder
 */
export const getOrCreateFolder = async (folderName: string, parentFolderId: string): Promise<string> => {
    const authClient = await getAuthClient();
    const drive = google.drive({ version: 'v3', auth: authClient as any });

    // Sanitize folder name slightly to avoid query issues
    const safeFolderName = folderName.replace(/'/g, "\\'");

    // Check if folder exists
    const query = `mimeType='application/vnd.google-apps.folder' and name='${safeFolderName}' and '${parentFolderId}' in parents and trashed=false`;

    try {
        const response = await drive.files.list({
            q: query,
            fields: 'files(id, name)',
            spaces: 'drive',
        });

        if (response.data.files && response.data.files.length > 0) {
            return response.data.files[0].id!;
        }

        // Create folder if not exists
        const fileMetadata = {
            name: folderName,
            mimeType: 'application/vnd.google-apps.folder',
            parents: [parentFolderId],
        };

        const folder = await drive.files.create({
            requestBody: fileMetadata,
            fields: 'id',
        });

        return folder.data.id!;
    } catch (error) {
        console.error('Error getting/creating folder:', error);
        throw error; // Propagate error
    }
};

/**
 * Check if the UTR already exists in the Google Sheet (Column K - index 10)
 */
export const checkDuplicateUTR = async (
    spreadsheetId: string,
    utr: string
): Promise<boolean> => {
    const authClient = await getAuthClient();
    const sheets = google.sheets({ version: 'v4', auth: authClient as any });
    const range = 'Sheet1!K:K'; // Assuming UTR is in Column K

    const response = await sheets.spreadsheets.values.get({
        spreadsheetId,
        range,
    });

    const rows = response.data.values;
    if (!rows || rows.length === 0) {
        return false;
    }

    const normalizedUTR = utr.trim().toUpperCase();
    const existingUTRs = rows.flat().map((val: any) => String(val).trim().toUpperCase());

    return existingUTRs.includes(normalizedUTR);
};

/**
 * Append a row to the Google Sheet
 */
export const appendRowToSheet = async (
    spreadsheetId: string,
    rowData: string[]
) => {
    const authClient = await getAuthClient();
    const sheets = google.sheets({ version: 'v4', auth: authClient as any });

    await sheets.spreadsheets.values.append({
        spreadsheetId,
        range: 'Sheet1!A:P',
        valueInputOption: 'USER_ENTERED',
        requestBody: {
            values: [rowData],
        },
    });
};

/**
 * Registration data type for analytics
 */
export interface RegistrationData {
    timestamp: string;
    registrationId: string;
    eventId: string;
    eventName: string;
    name: string;
    email: string;
    rollNo: string;
    department: string;
    utrId: string;
    amount: number;
    driveFileId: string;
    driveViewUrl: string;
    driveDownloadUrl: string;
    status: string;
    checkedInAt?: string;
    teamMembers?: string; // JSON string of team members from Column P
}

/**
 * Fetch all registrations from Google Sheet for analytics
 */
export const getAllRegistrations = async (spreadsheetId: string): Promise<RegistrationData[]> => {
    const authClient = await getAuthClient();
    const sheets = google.sheets({ version: 'v4', auth: authClient as any });

    const response = await sheets.spreadsheets.values.get({
        spreadsheetId,
        range: 'Sheet1!A:P', // Include column P for teamMembers
    });

    const rows = response.data.values;
    if (!rows || rows.length <= 1) return []; // Skip header row or empty

    // Map rows to objects (skip header)
    return rows.slice(1).map(row => ({
        timestamp: row[0] || '',
        registrationId: row[1] || '',
        eventId: row[2] || '',
        eventName: row[3] || '',
        name: row[4] || '',
        email: row[5] || '',
        rollNo: row[6] || '',
        department: row[7] || '',
        utrId: row[8] || '',
        amount: parseFloat(row[9]) || 0,
        driveFileId: row[10] || '',
        driveViewUrl: row[11] || '',
        driveDownloadUrl: row[12] || '',
        status: row[13] || 'PENDING',
        checkedInAt: row[14] || '',
        teamMembers: row[15] || '' // Column P - Team Members JSON
    }));
};

/**
 * Update registration status in Google Sheet
 * Status column is N (index 13, 1-based column 14)
 */
export const updateRegistrationStatus = async (
    spreadsheetId: string,
    registrationId: string,
    newStatus: string
): Promise<{ success: boolean; rowNumber?: number; error?: string }> => {
    const authClient = await getAuthClient();
    const sheets = google.sheets({ version: 'v4', auth: authClient as any });

    try {
        // First, find the row with this registration ID (Column B)
        const response = await sheets.spreadsheets.values.get({
            spreadsheetId,
            range: 'Sheet1!B:B', // Registration ID column
        });

        const rows = response.data.values;
        if (!rows || rows.length === 0) {
            return { success: false, error: 'No registrations found' };
        }

        // Find the row index (1-indexed for sheets, +1 for header)
        const rowIndex = rows.findIndex((row, idx) =>
            idx > 0 && row[0] === registrationId
        );

        if (rowIndex === -1) {
            return { success: false, error: 'Registration not found' };
        }

        // Row number in sheet (1-indexed, +1 for header compensation)
        const sheetRowNumber = rowIndex + 1;

        // Update the status column (N)
        await sheets.spreadsheets.values.update({
            spreadsheetId,
            range: `Sheet1!N${sheetRowNumber}`,
            valueInputOption: 'USER_ENTERED',
            requestBody: {
                values: [[newStatus]]
            }
        });

        return { success: true, rowNumber: sheetRowNumber };
    } catch (error) {
        console.error('Error updating registration status:', error);
        return { success: false, error: 'Failed to update status' };
    }
};

/**
 * Get a single registration by ID
 */
export const getRegistrationById = async (
    spreadsheetId: string,
    registrationId: string
): Promise<RegistrationData | null> => {
    const registrations = await getAllRegistrations(spreadsheetId);
    return registrations.find(r => r.registrationId === registrationId) || null;
};

/**
 * Announcement Data Type
 */
export interface AnnouncementData {
    id: string;
    title: string;
    content: string;
    category: string;
    date: string;
    postedBy: string;
}

/**
 * Helper: Check if a sheet (tab) exists, and create it if not.
 */
const ensureSheetExists = async (spreadsheetId: string, title: string) => {
    const authClient = await getAuthClient();
    const sheets = google.sheets({ version: 'v4', auth: authClient as any });

    try {
        const response = await sheets.spreadsheets.get({
            spreadsheetId,
        });

        const sheet = response.data.sheets?.find(s => s.properties?.title === title);
        if (!sheet) {
            // Create the sheet
            await sheets.spreadsheets.batchUpdate({
                spreadsheetId,
                requestBody: {
                    requests: [
                        {
                            addSheet: {
                                properties: {
                                    title,
                                    gridProperties: {
                                        rowCount: 1000,
                                        columnCount: 10
                                    }
                                }
                            }
                        }
                    ]
                }
            });

            // Add Headers
            await sheets.spreadsheets.values.update({
                spreadsheetId,
                range: `${title}!A1:F1`,
                valueInputOption: 'USER_ENTERED',
                requestBody: {
                    values: [['ID', 'Title', 'Content', 'Category', 'Date', 'PostedBy']]
                }
            });
        }
    } catch (error) {
        console.error(`Error ensuring sheet '${title}' exists:`, error);
        throw error;
    }
};

/**
 * Fetch all announcements from Google Sheet (Announcements Tab)
 */
export const getAnnouncements = async (spreadsheetId: string): Promise<AnnouncementData[]> => {
    const authClient = await getAuthClient();
    const sheets = google.sheets({ version: 'v4', auth: authClient as any });

    try {
        // Ensure sheet exists before reading
        await ensureSheetExists(spreadsheetId, 'Announcements');

        const response = await sheets.spreadsheets.values.get({
            spreadsheetId,
            range: 'Announcements!A:F',
        });

        const rows = response.data.values;
        if (!rows || rows.length <= 1) return []; // Skip header

        return rows.slice(1).map((row) => ({
            id: row[0] || '',
            title: row[1] || '',
            content: row[2] || '',
            category: row[3] || '',
            date: row[4] || '',
            postedBy: row[5] || 'Admin',
        })).reverse(); // Newest first
    } catch (error) {
        console.warn("Could not fetch announcements:", error);
        return [];
    }
};

/**
 * Create a new announcement
 */
export const createAnnouncement = async (
    spreadsheetId: string,
    announcement: AnnouncementData
) => {
    const authClient = await getAuthClient();
    const sheets = google.sheets({ version: 'v4', auth: authClient as any });

    await ensureSheetExists(spreadsheetId, 'Announcements');

    const rowData = [
        announcement.id,
        announcement.title,
        announcement.content,
        announcement.category,
        announcement.date,
        announcement.postedBy
    ];

    try {
        await sheets.spreadsheets.values.append({
            spreadsheetId,
            range: 'Announcements!A:F',
            valueInputOption: 'USER_ENTERED',
            requestBody: {
                values: [rowData],
            },
        });
    } catch (error: any) {
        console.error("Error creating announcement:", error);
        throw error;
    }
};

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';

/**
 * Creates a Supabase client for use in Server Components, Route Handlers, and Server Actions.
 * This client reads cookies to maintain the user session.
 */
export async function createClient() {
    const cookieStore = await cookies();

    return createServerClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
        {
            cookies: {
                getAll() {
                    return cookieStore.getAll();
                },
                setAll(cookiesToSet) {
                    try {
                        cookiesToSet.forEach(({ name, value, options }) =>
                            cookieStore.set(name, value, options)
                        );
                    } catch {
                        // The `setAll` method was called from a Server Component.
                        // This can be ignored if you have middleware refreshing sessions.
                    }
                },
            },
        }
    );
}

/**
 * Creates a Supabase Admin client with service role access.
 * Use this ONLY in secure server-side contexts (never expose to client).
 */
export function createAdminClient() {
    const { createClient } = require('@supabase/supabase-js');

    return createClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL,
        process.env.SUPABASE_SERVICE_ROLE_KEY,
        {
            auth: {
                autoRefreshToken: false,
                persistSession: false
            }
        }
    );
}
